-- =============================================================================
-- 494 — LE CAHIER D'EXERCICES DE 3E (partie 8)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 494 --niveau 3e --fichiers allemand.n1,allemand.n2 --suffixe 8 > supabase/contenu/494_exercices_3e_8.sql
--
-- 72 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.n1             36 exercices · 12 chapitres
--   allemand.n2             36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('d4002fe0-91d7-56ae-b36b-981cef0e2b98'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un courriel pour Frau Weber","competence":"manier-langue","situation":"Mia écrit à sa professeure d’allemand pour lui proposer une sortie. Relis son courriel et observe ses majuscules.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Die E-Mail von Mia","blocs":["Sehr geehrte Frau Weber,","ich möchte Sie fragen, ob Sie am Freitag Zeit haben. Meine Freunde kommen auch, sie sind sehr nett.","Mit freundlichen Grüßen\nMia Keller"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots du courriel qui sont le « vous » de politesse.","aide":"Cherche le mot écrit avec une majuscule au milieu de la phrase, alors qu’il n’est pas un nom.","type":"zone","document":"mail","multiple":true},{"enonce":"Pourquoi Mia écrit-elle « Sie » avec un S majuscule dans « ob Sie am Freitag Zeit haben » ?","aide":"Regarde à qui Mia s’adresse : elle vouvoie sa professeure.","type":"choix","options":[{"id":"a","texte":"C’est un nom propre, comme Mia ou Berlin"},{"id":"b","texte":"C’est le premier mot d’une phrase, donc une majuscule"},{"id":"c","texte":"C’est le « Sie » de politesse, qui prend toujours la majuscule"},{"id":"d","texte":"C’est un verbe devenu nom, comme das Essen"}],"multiple":false},{"enonce":"Que signifie « sie sind sehr nett » dans la dernière phrase du courriel ?","aide":"Le verbe est « sind » et le mot « sie » est écrit avec une minuscule.","type":"choix","options":[{"id":"a","texte":"ils sont très gentils"},{"id":"b","texte":"elle est très gentille"},{"id":"c","texte":"vous êtes très gentil"},{"id":"d","texte":"je suis très gentil"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m9"]},"explication":"Les deux **Sie** désignent Frau Weber : le « Sie » de politesse garde toujours sa majuscule, même au milieu d’une phrase."},{"cle":{"type":"choix","ids":["c"]},"explication":"Mia vouvoie Frau Weber : **Sie, Ihnen, Ihr** s’écrivent toujours avec une majuscule quand ils signifient « vous » de politesse."},{"cle":{"type":"choix","ids":["a"]},"explication":"**sie sind** = « ils / elles sont » : minuscule, donc ce n’est pas le « vous » de politesse, et « sind » est une forme de pluriel. Il reprend « meine Freunde »."}]$ex$::jsonb),
  ('d4002fe0-91d7-56ae-b36b-981cef0e2b98'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Cinq phrases de Lukas à corriger","competence":"manier-langue","situation":"Lukas s’entraîne à écrire en allemand. Sa professeure a relevé cinq de ses phrases : une seule est parfaitement ponctuée.","documents":[{"id":"saetze","type":"tableau","titre":"Fünf Sätze von Lukas","colonnes":["Satz"],"lignes":[["Ich lerne Deutsch um in Berlin zu studieren."],["Er ist arm, aber glücklich."],["Ich weiß dass er kommt."],["Ich lese, und ich schreibe."],["Das Buch das ich lese ist spannend."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche la seule phrase du tableau qui est correctement ponctuée.","aide":"Cherche la phrase où la virgule est devant « aber » : cette conjonction l’exige.","type":"zone","document":"saetze","multiple":false},{"enonce":"Touche la phrase qui contient une virgule en trop.","aide":"Regarde ce qu’on met devant « und » dans une énumération ou une coordination simple.","type":"zone","document":"saetze","multiple":false},{"enonce":"Combien de virgules faut-il ajouter dans la dernière phrase : « Das Buch das ich lese ist spannend » ?","aide":"La relative « das ich lese » est enchâssée dans la phrase : que faut-il de chaque côté ?","type":"nombre"},{"enonce":"Dans la première phrase, pourquoi faut-il une virgule devant « um in Berlin zu studieren » ?","aide":"Pense aux trois groupes infinitifs à virgule obligatoire : um… zu, ohne… zu, statt… zu.","type":"choix","options":[{"id":"a","texte":"Le verbe studieren est à l’infinitif, comme tout infinitif"},{"id":"b","texte":"Un groupe introduit par um… zu exige toujours la virgule"},{"id":"c","texte":"Le mot Berlin est un nom propre qui impose une virgule"},{"id":"d","texte":"Toute phrase allemande doit avoir au moins une virgule"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"**Er ist arm, aber glücklich.** : la virgule devant *aber* est obligatoire. Les autres phrases oublient une virgule, ou en ajoutent une de trop."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"**Ich lese, und ich schreibe** : en principe, il n’y a pas de virgule devant *und* ni devant *oder*. On écrit : *Ich lese und ich schreibe.*"},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Une subordonnée enchâssée est encadrée de **deux** virgules : *Das Buch, das ich lese, ist spannend.*"},{"cle":{"type":"choix","ids":["b"]},"explication":"Le groupe **um… zu** (le but) est toujours précédé d’une virgule : *Ich lerne Deutsch, um in Berlin zu studieren.*"}]$ex$::jsonb),
  ('d4002fe0-91d7-56ae-b36b-981cef0e2b98'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le brouillon de Karl","competence":"manier-langue","situation":"Karl a écrit à toute vitesse, sans aucune virgule. Il cite aussi son frère à la française. Aide-le à remettre de l’ordre.","documents":[{"id":"brouillon","type":"texte","genre":"lettre","titre":"Karls Entwurf","blocs":["Mein Bruder sagt dass ich Deutsch lerne um in Wien zu studieren aber ich weiß nicht ob ich das schaffe"],"source":"Brouillon écrit pour l’exercice"},{"id":"zitat","type":"dialogue","modele":"sms","titre":"Karl und Lea","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Karl","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Was sagt dein Bruder?"},{"qui":"Karl","texte":"Er sagt, “Ich komme morgen.”"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Combien de virgules faut-il dans le brouillon de Karl pour qu’il soit correctement ponctué ?","aide":"Une virgule devant la subordonnée en « dass », une devant « um… zu », une devant « aber » et une devant la subordonnée en « ob ».","type":"nombre"},{"enonce":"Touche le mot du brouillon qui s’écrit avec ss, parce que la voyelle qui précède est brève.","aide":"Un seul mot du texte s’écrit « ss » ; celui avec « ß » est un leurre.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Associe chaque mot à la règle d’écriture qui explique son orthographe.","aide":"Prononce chaque mot : la voyelle est-elle brève, longue ou une diphtongue ?","type":"association","gauche":[{"id":"g0","texte":"der Fluss"},{"id":"g1","texte":"die Straße"},{"id":"g2","texte":"heißen"}],"droite":[{"id":"d0","texte":"ß après une diphtongue"},{"id":"d1","texte":"ss après une voyelle brève"},{"id":"d2","texte":"ß après une voyelle longue"}]},{"enonce":"Karl cite son frère à la française dans le message à Lea. Quelle correction apporter ?","aide":"En allemand, on annonce le discours direct par des deux-points et on ouvre les guillemets en bas.","type":"choix","options":[{"id":"a","texte":"Supprimer les guillemets et garder simplement la virgule"},{"id":"b","texte":"Deux-points, puis guillemets bas à l’ouverture et haut à la fermeture"},{"id":"c","texte":"Guillemets français « » avec espaces, la virgule étant conservée"},{"id":"d","texte":"Un point-virgule à la place de la virgule, guillemets inchangés"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Quatre virgules : *Mein Bruder sagt, dass ich Deutsch lerne, um in Wien zu studieren, aber ich weiß nicht, ob ich das schaffe.* (devant dass, um, aber et ob)."},{"cle":{"type":"zone","ids":["m3"]},"explication":"**dass** s’écrit avec *ss* : la voyelle *a* est brève. À l’inverse, *weiß* prend ß (voyelle longue ou diphtongue)."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Fluss** : voyelle brève, donc *ss*. **Straße** : voyelle longue, donc *ß*. **heißen** : diphtongue *ei*, donc *ß*."},{"cle":{"type":"choix","ids":["b"]},"explication":"On écrit : *Er sagt: „Ich komme morgen.“* — **deux-points** avant la citation, guillemets **en bas** à l’ouverture et **en haut** à la fermeture."}]$ex$::jsonb),
  ('207ad1d8-f8be-5943-84f5-61eaa5344b1d'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Que font Pia et Ali samedi ?","competence":"comprendre-langue","situation":"Pia et Ali échangent des messages sur leurs projets du week-end. Observe où se trouve le verbe dans chaque phrase.","documents":[{"id":"plaene","type":"dialogue","modele":"sms","titre":"Pläne fürs Wochenende","participants":[{"nom":"Pia","emoji":"👧","cote":"gauche"},{"nom":"Ali","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Pia","texte":"Was machst du am Samstag?"},{"qui":"Ali","texte":"Am Samstag fahre ich nach Köln."},{"qui":"Pia","texte":"Toll! Ich bleibe zu Hause."},{"qui":"Ali","texte":"Heute Abend spiele ich Fußball."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les quatre verbes conjugués de la conversation.","aide":"Cherche le mot qui change avec la personne : machst, fahre…","type":"zone","document":"plaene","multiple":true},{"enonce":"Dans « Am Samstag fahre ich nach Köln », qu’y a-t-il à la première place, devant le verbe ?","aide":"La règle compte des groupes, pas des mots.","type":"choix","options":[{"id":"a","texte":"Le seul mot « Samstag », sans « am »"},{"id":"b","texte":"Le sujet « ich », toujours premier"},{"id":"c","texte":"Le verbe « fahre » lui-même, seul"},{"id":"d","texte":"Le groupe « Am Samstag », en deux mots"}],"multiple":false},{"enonce":"Remets les éléments dans l’ordre pour dire « Demain, je vais à Berlin ». La phrase commence par Morgen.","aide":"Le verbe conjugué est toujours deuxième. Où passe donc le sujet ?","type":"ordre","items":[{"id":"a","texte":"Morgen"},{"id":"b","texte":"fahre"},{"id":"c","texte":"nach Berlin"},{"id":"d","texte":"ich"}]},{"enonce":"Complète la phrase : « Aujourd’hui, je vais au cinéma. »","aide":"Le sujet est « ich » : quelle terminaison au présent ?","type":"trous","segments":["Heute ",0," ich ins Kino."],"banque":["gehen","geht","gehst","gehe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m7","m13","m18"]},"explication":"Les verbes conjugués sont **machst, fahre, bleibe, spiele**. Dans chaque phrase, ils sont à la deuxième place."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le verbe occupe la deuxième **place**, non le deuxième mot : « Am Samstag » forme un seul groupe, et *fahre* vient juste derrière."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"**Morgen fahre ich nach Berlin.** Le groupe *Morgen* ouvre la phrase, le verbe suit, le sujet passe derrière : c’est l’inversion."},{"cle":{"type":"trous","trous":[["gehe"]]},"affichage":"gehe","explication":"**Heute gehe ich ins Kino.** *Heute* ouvre la phrase, le verbe conjugué *gehe* est deuxième, le sujet *ich* passe derrière."}]$ex$::jsonb),
  ('207ad1d8-f8be-5943-84f5-61eaa5344b1d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le courriel à Oma","competence":"manier-langue","situation":"Tom écrit à sa grand-mère pour lui raconter sa semaine. Dans chaque phrase, le verbe est en deux morceaux : l’un à la deuxième place, l’autre à la fin.","documents":[{"id":"oma","type":"texte","genre":"lettre","titre":"Die E-Mail an Oma","blocs":["Liebe Oma,","gestern habe ich einen Film gesehen. Heute muss ich Hausaufgaben machen. Morgen stehe ich früh auf.","Liebe Grüße\nTom"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots qui ferment une phrase du courriel : un participe, un infinitif et un préverbe.","aide":"Cherche le dernier mot de chacune des trois phrases (avant le point).","type":"zone","document":"oma","multiple":true},{"enonce":"Quel type de « parenthèse verbale » forme « habe … gesehen » ?","aide":"Regarde l’auxiliaire « habe » et la forme du dernier mot.","type":"choix","options":[{"id":"a","texte":"Un modal suivi d’un infinitif"},{"id":"b","texte":"Un verbe à préverbe séparable"},{"id":"c","texte":"Un temps composé : auxiliaire puis participe"},{"id":"d","texte":"Une subordonnée avec le verbe à la fin"}],"multiple":false},{"enonce":"Remets les éléments en ordre : « Ce soir, je dois travailler. » La phrase commence par Heute Abend.","aide":"Le modal est conjugué en deuxième place, l’infinitif part à la fin.","type":"ordre","items":[{"id":"a","texte":"arbeiten"},{"id":"b","texte":"Heute Abend"},{"id":"c","texte":"ich"},{"id":"d","texte":"muss"}]},{"enonce":"Complète : « Je me lève à sept heures demain. » (aufstehen)","aide":"Le verbe se coupe en deux : le radical conjugué d’abord, le préverbe à la toute fin.","type":"trous","segments":["Ich ",0," morgen um sieben Uhr ",1,"."],"banque":["steht","auf","stehe","an"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12","m17"]},"explication":"**gesehen** (participe), **machen** (infinitif avec muss) et **auf** (préverbe de *aufstehen*) ferment chacun leur phrase."},{"cle":{"type":"choix","ids":["c"]},"explication":"**habe … gesehen** : l’auxiliaire *haben* est à la deuxième place, le participe passé *gesehen* ferme la phrase."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"**Heute Abend muss ich arbeiten.** Le modal *muss* est deuxième, le sujet suit, et l’infinitif *arbeiten* ferme la phrase."},{"cle":{"type":"trous","trous":[["stehe"],["auf"]]},"affichage":"stehe · auf","explication":"**Ich stehe morgen um sieben Uhr auf.** *stehe* est à la deuxième place, le préverbe *auf* est rejeté en fin de phrase."}]$ex$::jsonb),
  ('207ad1d8-f8be-5943-84f5-61eaa5344b1d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le voyage de Selin","competence":"raisonner","situation":"Selin organise un voyage et offre des cadeaux. Utilise l’agenda et la conversation pour construire des phrases à l’ordre irréprochable.","documents":[{"id":"reise","type":"tableau","titre":"Selins Reiseplan","colonnes":["Wie?","Wohin?","Wann?","Warum?"],"lignes":[["mit dem Zug","nach München","morgen","wegen der Arbeit"]],"enteteLignes":false,"source":"Agenda écrit pour l’exercice"},{"id":"geschenk","type":"dialogue","modele":"sms","titre":"Geschenke","participants":[{"nom":"Selin","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Selin","texte":"Was schenkst du Oma?"},{"qui":"Tom","texte":"Ich gebe der Oma das Buch."},{"qui":"Selin","texte":"Und das Heft?"},{"qui":"Tom","texte":"Ich gebe es dem Opa."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche, dans l’agenda, la case qui donne la cause du voyage.","aide":"La cause répond à la question « Warum ? ».","type":"zone","document":"reise","multiple":false},{"enonce":"Selin dit son voyage dans l’ordre neutre. Complète la phrase « Ich fahre… » avec les quatre compléments de l’agenda.","aide":"Retiens TeKaMoLo : temps, cause, manière, lieu.","type":"ordre","items":[{"id":"a","texte":"nach München"},{"id":"b","texte":"morgen"},{"id":"c","texte":"wegen der Arbeit"},{"id":"d","texte":"mit dem Zug"}]},{"enonce":"Touche le pronom qui a pris la place d’un nom accusatif et se trouve donc devant le datif « dem Opa ».","aide":"Il remplace « das Heft » et se place juste après le verbe.","type":"zone","document":"geschenk","multiple":false},{"enonce":"Comment dire « Je le lui donne » (le livre, à Oma) ?","aide":"Quand l’accusatif est un pronom, il passe devant le datif.","type":"choix","options":[{"id":"a","texte":"Ich ihr gebe es."},{"id":"b","texte":"Ich gebe es ihr."},{"id":"c","texte":"Ich gebe ihr es."},{"id":"d","texte":"Ich gebe ihr das."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"**wegen der Arbeit** répond à *Warum ?* : c’est le complément de cause (Ka)."},{"cle":{"type":"ordre","ids":["b","c","d","a"]},"explication":"**Ich fahre morgen wegen der Arbeit mit dem Zug nach München.** Ordre TeKaMoLo : Temps, Cause, Manière, Lieu."},{"cle":{"type":"zone","ids":["m15"]},"explication":"**es** remplace *das Heft* : un accusatif pronom passe devant le datif — *Ich gebe es dem Opa* — alors que deux noms suivent l’ordre datif puis accusatif."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Ich gebe es ihr.** Le pronom accusatif *es* se place immédiatement après le verbe, devant le datif *ihr*."}]$ex$::jsonb),
  ('e1175a92-f062-5eef-b96e-27f9e4ce6cf0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un nouveau dans la classe","competence":"comprendre-langue","situation":"Leon fait connaissance avec Mina, qui vient d’arriver dans sa classe. Observe les questions qu’ils se posent.","documents":[{"id":"kennen","type":"dialogue","modele":"sms","titre":"Neue Mitschülerin","participants":[{"nom":"Leon","emoji":"👦","cote":"gauche"},{"nom":"Mina","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leon","texte":"Hallo! Wie heißt du?"},{"qui":"Mina","texte":"Ich heiße Mina. Und du?"},{"qui":"Leon","texte":"Ich bin Leon. Woher kommst du?"},{"qui":"Mina","texte":"Aus Hamburg. Wohnst du auch hier?"},{"qui":"Leon","texte":"Ja, ich wohne in der Nähe der Schule."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot interrogatif qui demande l’origine : « d’où viens-tu ? ».","aide":"Le mot interrogatif est collé au début de la question de Leon sur la ville de Mina.","type":"zone","document":"kennen","multiple":false},{"enonce":"Touche le verbe qui ouvre la question fermée (celle à laquelle on répond par oui ou non).","aide":"Dans une question fermée, il n’y a pas de mot en w- : le verbe passe en tête.","type":"zone","document":"kennen","multiple":false},{"enonce":"Associe chaque mot interrogatif à son sens.","aide":"Le « hin » indique le mouvement vers un but, le « her » l’origine.","type":"association","gauche":[{"id":"g0","texte":"wo"},{"id":"g1","texte":"wohin"},{"id":"g2","texte":"woher"}],"droite":[{"id":"d0","texte":"où, vers quel lieu"},{"id":"d1","texte":"d’où"},{"id":"d2","texte":"où, sans mouvement"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"**Woher** = « d’où ». Il demande l’origine, alors que *wo* demande le lieu sans mouvement."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**Wohnst** ouvre « Wohnst du auch hier ? » : dans une question fermée, le verbe conjugué est en première position."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**wo** = où (on est), **wohin** = où (on va), **woher** = d’où (on vient)."}]$ex$::jsonb),
  ('e1175a92-f062-5eef-b96e-27f9e4ce6cf0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le training de Paul","competence":"manier-langue","situation":"Nora et Paul parlent de leur entraînement. Le dialogue contient une question négative et une question indirecte.","documents":[{"id":"training","type":"dialogue","modele":"sms","titre":"Nach der Schule","participants":[{"nom":"Nora","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nora","texte":"Kommst du heute nicht zum Training?"},{"qui":"Paul","texte":"Doch, ich komme. Wann beginnt es?"},{"qui":"Nora","texte":"Ich weiß nicht, wann der Trainer kommt."},{"qui":"Paul","texte":"Dann frage ich ihn, ob wir heute früher anfangen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot par lequel Paul contredit la question négative de Nora.","aide":"Paul veut dire « si ! » : ce n’est pas ja.","type":"zone","document":"training","multiple":false},{"enonce":"On te demande « Hast du keinen Hunger ? » et tu as faim. Que réponds-tu ?","aide":"La question est négative : il faut contredire.","type":"choix","options":[{"id":"a","texte":"Ja ! Ich habe Hunger."},{"id":"b","texte":"Nicht ! Ich habe Hunger."},{"id":"c","texte":"Nein ! Ich habe Hunger."},{"id":"d","texte":"Doch ! Ich habe Hunger."}],"multiple":false},{"enonce":"Remets en ordre la question indirecte « Ich weiß nicht, … ».","aide":"Dans une subordonnée, le verbe conjugué va tout à la fin.","type":"ordre","items":[{"id":"a","texte":"der Zug"},{"id":"b","texte":"wann"},{"id":"c","texte":"abfährt"}]},{"enonce":"Complète la question indirecte : « Je me demande s’il vient. »","aide":"Le « si » d’une question indirecte exprime une alternative.","type":"trous","segments":["Ich frage mich, ",0," er kommt."],"banque":["dass","wenn","wann","ob"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**Doch** contredit une question négative ou une affirmation négative : « si ! »."},{"cle":{"type":"choix","ids":["d"]},"explication":"Face à une question négative, on contredit par **Doch** : *Doch ! Ich habe Hunger.* Ici, *ja* serait impossible."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"**Ich weiß nicht, wann der Zug abfährt.** Question indirecte : mot interrogatif, sujet, puis le verbe conjugué à la fin."},{"cle":{"type":"trous","trous":[["ob"]]},"affichage":"ob","explication":"**Ich frage mich, ob er kommt.** *ob* traduit le « si » d’une alternative ; *wenn* introduit une condition ou un moment."}]$ex$::jsonb),
  ('e1175a92-f062-5eef-b96e-27f9e4ce6cf0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une classe en route pour Vienne","competence":"analyser-document","situation":"La classe de Herr Berg part en voyage scolaire à Vienne. Lis l’affiche, puis choisis le bon mot interrogatif pour chaque information.","documents":[{"id":"plakat","type":"fiche","modele":"affiche","entete":"Klassenfahrt nach Wien","sousTitre":"Klasse 3b","emoji":"🚆","lignes":[{"texte":"Wir fahren mit dem Zug nach Wien.","id":"z1"},{"texte":"Wir treffen uns um acht Uhr.","id":"z2"},{"texte":"Wir warten am Bahnhof auf Herrn Berg, unseren Lehrer.","id":"z3"},{"texte":"Wir denken schon an die Stadtführung.","id":"z4"}],"pied":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui répond à la question « Auf wen warten wir ? ».","aide":"La question porte sur une personne : cherche qui on attend.","type":"zone","document":"plakat","multiple":false},{"enonce":"Associe chaque réponse à la question qui la provoque.","aide":"Pour une chose, wo(r)- + préposition ; pour une personne, préposition + wen / wem.","type":"association","gauche":[{"id":"g0","texte":"Ich schreibe mit einem Stift."},{"id":"g1","texte":"Ich spreche mit meiner Lehrerin."},{"id":"g2","texte":"Ich denke an die Prüfung."},{"id":"g3","texte":"Ich warte auf den Bus."}],"droite":[{"id":"d0","texte":"Mit wem sprichst du?"},{"id":"d1","texte":"Womit schreibst du?"},{"id":"d2","texte":"Woran denkst du?"},{"id":"d3","texte":"Worauf wartest du?"}]},{"enonce":"Touche la ligne qui répond à la question « Woran denken wir schon ? ».","aide":"Cherche le verbe « denken » suivi de sa préposition.","type":"zone","document":"plakat","multiple":false},{"enonce":"Complète la question dont la réponse est « An die Prüfung ».","aide":"On interroge sur une chose avec wo(r)- + préposition.","type":"trous","segments":[0," denkst du? — An die Prüfung."],"banque":["An wen","Wohin","Woran","Wofür"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Wir warten am Bahnhof auf Herrn Berg** : on interroge sur une personne avec *auf wen*, la préposition étant suivie du pronom au cas voulu."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"Chose : **womit, woran, worauf**. Personne : **mit wem** (datif après mit), *auf wen*, *an wen*."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**Wir denken schon an die Stadtführung** : *an die Stadtführung* est une chose, donc on demande *woran*."},{"cle":{"type":"trous","trous":[["woran"]]},"affichage":"Woran","explication":"**Woran denkst du ?** *Woran* = *wo* + *r* + *an* : on interroge sur une chose, jamais sur une personne."}]$ex$::jsonb),
  ('ef7cf249-6775-5a8f-9bf4-723c10a95419'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un café sans café","competence":"comprendre-langue","situation":"Emre est assis à la terrasse d’un café. Il refuse presque tout ce que la serveuse lui propose.","documents":[{"id":"cafe","type":"dialogue","modele":"sms","titre":"Im Café","participants":[{"nom":"Kellnerin","emoji":"☕","cote":"gauche"},{"nom":"Emre","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Kellnerin","texte":"Guten Tag! Möchten Sie einen Kaffee?"},{"qui":"Emre","texte":"Nein, danke. Ich trinke keinen Kaffee."},{"qui":"Kellnerin","texte":"Und etwas zu essen? Wir haben Kuchen und Kekse."},{"qui":"Emre","texte":"Ich esse keinen Kuchen und keine Kekse."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois formes de « kein » dans les réponses d’Emre.","aide":"Cherche les mots qui commencent par « kein-».","type":"zone","document":"cafe","multiple":true},{"enonce":"Pourquoi Emre dit-il « keinen Kaffee » et non « nicht Kaffee » ?","aide":"Le nom « Kaffee » est employé sans article.","type":"choix","options":[{"id":"a","texte":"Le verbe trinken exige toujours la forme kein"},{"id":"b","texte":"Nicht ne peut jamais se placer après un verbe"},{"id":"c","texte":"Kaffee est un mot étranger, donc invariable"},{"id":"d","texte":"Le nom n’a pas d’article défini : on nie par kein"}],"multiple":false},{"enonce":"Complète pour dire : « Je n’ai pas de voiture et pas de sœur. »","aide":"Auto est neutre ; Schwester est féminin.","type":"trous","segments":["Ich habe ",0," Auto und ",1," Schwester."],"banque":["keinen","nicht","kein","keine"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m23","m26"]},"explication":"**keinen, keinen, keine** : *kein* se décline comme *ein*, et prend la terminaison selon le genre et le cas du nom."},{"cle":{"type":"choix","ids":["d"]},"explication":"Devant un nom précédé de *ein* ou **sans article**, on nie avec **kein** : *Ich trinke keinen Kaffee.*"},{"cle":{"type":"trous","trous":[["kein"],["keine"]]},"affichage":"kein · keine","explication":"**Ich habe kein Auto und keine Schwester.** *kein* devant un neutre (*das Auto*), *keine* devant un féminin (*die Schwester*)."}]$ex$::jsonb),
  ('ef7cf249-6775-5a8f-9bf4-723c10a95419'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les phrases négatives de Zoé","competence":"manier-langue","situation":"Zoé s’entraîne à placer « nicht » dans ses phrases. Observe où il se trouve selon ce qu’elle nie.","documents":[{"id":"nicht","type":"tableau","titre":"Fünf negative Sätze","colonnes":["Satz"],"lignes":[["Ich habe ihn gestern nicht gesehen."],["Ich gehe nicht ins Kino."],["Ich lese das Buch nicht."],["Das Buch ist nicht interessant."],["Ich fahre nicht morgen, sondern heute."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche la phrase où « nicht » est le dernier mot, parce que le complément d’objet direct est défini.","aide":"Cherche la phrase qui se termine par « nicht ».","type":"zone","document":"nicht","multiple":false},{"enonce":"Touche la phrase où « nicht » ne nie qu’un seul mot et se place devant lui.","aide":"Cherche la phrase qui rectifie : « pas demain, mais aujourd’hui ».","type":"zone","document":"nicht","multiple":false},{"enonce":"Remets en ordre pour nier toute la phrase « Ich habe das Buch gelesen ». La phrase commence par « Ich habe ».","aide":"Quand on nie toute la phrase, nicht se place devant le second morceau du verbe.","type":"ordre","items":[{"id":"a","texte":"gelesen"},{"id":"b","texte":"nicht"},{"id":"c","texte":"das Buch"}]},{"enonce":"Dans « Das Buch ist nicht interessant », pourquoi « nicht » est-il devant « interessant » ?","aide":"Interessant décrit le livre après le verbe sein.","type":"choix","options":[{"id":"a","texte":"Il nie un lieu avec mouvement : il va à la fin"},{"id":"b","texte":"Il nie un COD défini : il se place après lui"},{"id":"c","texte":"Il nie un verbe seul : il va avant le sujet"},{"id":"d","texte":"Il nie un attribut : il se place devant lui"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Ich lese das Buch nicht.** : le COD *das Buch* est défini, *nicht* se place après lui, tout à droite."},{"cle":{"type":"zone","ids":["r4c0"]},"explication":"**Ich fahre nicht morgen, sondern heute.** : *nicht* nie seulement *morgen*, et *sondern* rectifie."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"**Ich habe das Buch nicht gelesen.** *nicht* se place le plus à droite possible, juste devant le participe qui ferme la phrase."},{"cle":{"type":"choix","ids":["d"]},"explication":"**nicht** se place devant l’attribut : *Das Buch ist nicht interessant.*"}]$ex$::jsonb),
  ('ef7cf249-6775-5a8f-9bf4-723c10a95419'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pourquoi Jan ne joue plus","competence":"analyser-document","situation":"Marie s’inquiète : Jan ne vient plus au training. Lis leur conversation et observe leurs mots de négation.","documents":[{"id":"training2","type":"dialogue","modele":"sms","titre":"Training","participants":[{"nom":"Marie","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marie","texte":"Kommst du heute zum Training?"},{"qui":"Jan","texte":"Nein, ich habe keine Zeit und ich bin nicht fit."},{"qui":"Marie","texte":"Du kommst nie! Ist das Problem das Wetter?"},{"qui":"Jan","texte":"Nicht das Wetter, sondern mein Knie. Ich spiele nicht mehr Fußball."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui nie le nom « Zeit » dans la première réponse de Jan.","aide":"Il se décline comme « ein » : cherche un mot de forme « kein- ».","type":"zone","document":"training2","multiple":false},{"enonce":"Associe chaque mot négatif à son sens.","aide":"Chaque mot négatif exprime un seul sens : un temps, une personne, un lieu…","type":"association","gauche":[{"id":"g0","texte":"nie"},{"id":"g1","texte":"niemand"},{"id":"g2","texte":"nirgends"},{"id":"g3","texte":"noch nicht"}],"droite":[{"id":"d0","texte":"nulle part"},{"id":"d1","texte":"jamais"},{"id":"d2","texte":"personne"},{"id":"d3","texte":"pas encore"}]},{"enonce":"Que signifie la phrase de Jan « Ich spiele nicht mehr Fußball » ?","aide":"Pense au sens de « mehr » dans « nicht mehr ».","type":"choix","options":[{"id":"a","texte":"Je ne joue jamais au football"},{"id":"b","texte":"Je ne joue plus au football"},{"id":"c","texte":"Je joue plus de football qu’avant"},{"id":"d","texte":"Je ne joue pas encore au football"}],"multiple":false},{"enonce":"Complète pour dire : « Je n’ai rien vu. »","aide":"Une seule négation suffit en allemand.","type":"trous","segments":["Ich habe ",0," gesehen."],"banque":["nicht","nichts","niemand","nie"]},{"enonce":"Pourquoi Jan emploie-t-il « sondern » dans « Nicht das Wetter, sondern mein Knie » ?","aide":"Jan nie « le temps » avant de dire quel est le vrai problème.","type":"choix","options":[{"id":"a","texte":"Il explique pourquoi il ne vient pas"},{"id":"b","texte":"Il oppose deux idées sans rien corriger"},{"id":"c","texte":"Il remplace aber dans toutes les phrases"},{"id":"d","texte":"Il rectifie une erreur après une négation"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**keine** nie *Zeit* (nom féminin sans article) : *ich habe keine Zeit*."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"**nie** = jamais, **niemand** = personne, **nirgends** = nulle part, **noch nicht** = pas encore."},{"cle":{"type":"choix","ids":["b"]},"explication":"**nicht mehr** = « ne… plus » : Jan jouait avant, mais ne joue plus."},{"cle":{"type":"trous","trous":[["nichts"]]},"affichage":"nichts","explication":"**Ich habe nichts gesehen.** Deux négations ne s’additionnent pas : on n’écrit jamais « nicht nichts »."},{"cle":{"type":"choix","ids":["d"]},"explication":"**sondern** rectifie après une négation (*nicht A, sondern B*), alors qu’**aber** oppose simplement."}]$ex$::jsonb),
  ('11c68cd1-ea30-5b98-85e0-3c026b8989a2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Lena reste à la maison","competence":"comprendre-langue","situation":"Lena est malade et prévient son ami Tom. Observe où se trouve le verbe dans leurs phrases à conjonction.","documents":[{"id":"krank","type":"dialogue","modele":"sms","titre":"Lena ist krank","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Ich bleibe heute zu Hause, weil ich krank bin."},{"qui":"Tom","texte":"Schade! Ich glaube, dass du bald wieder gesund bist."},{"qui":"Lena","texte":"Danke! Weißt du, ob wir morgen Mathe haben?"},{"qui":"Tom","texte":"Ich weiß es nicht, aber ich frage Frau Roth."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois conjonctions de subordination de la conversation : celles qui envoient le verbe conjugué à la fin.","aide":"Cherche les mots qui précèdent un sujet et un verbe final : « parce que », « que », « si ».","type":"zone","document":"krank","multiple":true},{"enonce":"Touche le verbe qui ferme la subordonnée « weil ich krank … ».","aide":"Dans une subordonnée, le verbe conjugué est le dernier mot.","type":"zone","document":"krank","multiple":false},{"enonce":"Associe chaque conjonction à son sens.","aide":"Relis les phrases de Lena et de Tom pour retrouver weil, dass et ob.","type":"association","gauche":[{"id":"g0","texte":"weil"},{"id":"g1","texte":"dass"},{"id":"g2","texte":"ob"},{"id":"g3","texte":"damit"}],"droite":[{"id":"d0","texte":"pour que"},{"id":"d1","texte":"que"},{"id":"d2","texte":"parce que"},{"id":"d3","texte":"si (une alternative)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m12","m21"]},"explication":"**weil, dass, ob** introduisent une subordonnée : le verbe conjugué part à la fin. « aber » est une conjonction de coordination : l’ordre ne change pas."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**bin** ferme la subordonnée : *…, weil ich krank bin.*"},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**weil** = parce que, **dass** = que, **ob** = si (alternative), **damit** = pour que (but)."}]$ex$::jsonb),
  ('11c68cd1-ea30-5b98-85e0-3c026b8989a2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les souvenirs de grand-mère","competence":"analyser-document","situation":"Oma raconte son enfance dans une lettre. Trois conjonctions de temps s’y cachent : als, wenn et wann.","documents":[{"id":"erinnerung","type":"texte","genre":"lettre","titre":"Omas Brief","blocs":["Als ich klein war, wohnte ich auf dem Land. Immer wenn es regnete, spielte ich im Stall. Als ich zehn wurde, zogen wir in die Stadt. Wenn ich heute meine Freundin besuche, sprechen wir noch von früher."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux conjonctions qui introduisent une période ou un événement unique du passé.","aide":"Cherche le mot qui traduit « quand » pour un fait qui n’est arrivé qu’une fois, sans répétition.","type":"zone","document":"erinnerung","multiple":true},{"enonce":"Pourquoi Oma écrit-elle « Immer wenn es regnete » et non « Immer als es regnete » ?","aide":"La pluie est tombée plusieurs fois, pas une seule.","type":"choix","options":[{"id":"a","texte":"Als ne peut jamais suivre le mot immer, même au passé"},{"id":"b","texte":"Le verbe regnete est au présent, donc wenn est obligatoire"},{"id":"c","texte":"La pluie revenait souvent : wenn exprime la répétition"},{"id":"d","texte":"Es regnete est une phrase sans sujet réel"}],"multiple":false},{"enonce":"Remets en ordre : « Quand j’étais petit, j’habitais à la campagne. »","aide":"La subordonnée ouvre la phrase : le verbe de la principale suit immédiatement la virgule.","type":"ordre","items":[{"id":"a","texte":"Als ich"},{"id":"b","texte":"auf dem Land"},{"id":"c","texte":"ich"},{"id":"d","texte":"wohnte"},{"id":"e","texte":"klein war,"}]},{"enonce":"Complète : « Quand j’ai le temps, je te rends visite. » (action qui se répète)","aide":"Une action qui se répète au présent se dit avec wenn.","type":"trous","segments":[0," ich Zeit habe, besuche ich dich."],"banque":["Wann","Wenn","Als","Weil"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m17"]},"explication":"Les deux **Als** (*Als ich klein war*, *Als ich zehn wurde*) introduisent un fait ou une période unique du passé. *wenn* exprime la répétition (*immer wenn*) ou le présent."},{"cle":{"type":"choix","ids":["c"]},"explication":"**wenn** sert à la répétition dans le passé (« chaque fois que »). **als** est réservé à un fait unique."},{"cle":{"type":"ordre","ids":["a","e","d","c","b"]},"explication":"**Als ich klein war, wohnte ich auf dem Land.** Verbe de la subordonnée à la fin, puis le verbe de la principale, puis le sujet."},{"cle":{"type":"trous","trous":[["wenn"]]},"affichage":"Wenn","explication":"**Wenn ich Zeit habe, besuche ich dich.** *wann* ne s’emploie que dans une question ; *als* concerne un fait unique du passé."}]$ex$::jsonb),
  ('11c68cd1-ea30-5b98-85e0-3c026b8989a2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une excuse bien écrite","competence":"manier-langue","situation":"Après une absence, un élève écrit à son professeur. Son courriel emploie plusieurs conjonctions, certaines de subordination, une seule de coordination.","documents":[{"id":"entschuldigung","type":"texte","genre":"lettre","titre":"Eine Entschuldigung","blocs":["Lieber Herr Braun,","ich konnte gestern nicht kommen, denn ich war krank. Weil ich Fieber hatte, blieb ich im Bett. Ich hoffe, dass Sie das verstehen. Obwohl ich noch müde bin, arbeite ich heute wieder.","Mit freundlichen Grüßen\nJonas"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction du courriel qui ne renvoie PAS le verbe à la fin de sa proposition.","aide":"Après cette conjonction, l’ordre est celui d’une phrase ordinaire : « ich war krank ».","type":"zone","document":"entschuldigung","multiple":false},{"enonce":"Remets en ordre la fin de la phrase « Ich bin müde, … » (« parce que j’ai beaucoup travaillé hier »).","aide":"Dans la subordonnée, l’auxiliaire conjugué ferme la phrase, après le participe.","type":"ordre","items":[{"id":"a","texte":"weil"},{"id":"b","texte":"habe"},{"id":"c","texte":"gearbeitet"},{"id":"d","texte":"ich"},{"id":"e","texte":"gestern lange"}]},{"enonce":"Touche le verbe de la principale qui suit immédiatement la subordonnée « Weil ich Fieber hatte, … ».","aide":"La subordonnée ouvre la phrase : le verbe de la principale vient tout de suite après la virgule.","type":"zone","document":"entschuldigung","multiple":false},{"enonce":"Laquelle de ces phrases est correcte ?","aide":"Après weil, le verbe conjugué est rejeté en fin de subordonnée.","type":"choix","options":[{"id":"a","texte":"Ich bleibe zu Hause, denn ich krank bin."},{"id":"b","texte":"Ich bleibe zu Hause, weil ich bin krank."},{"id":"c","texte":"Ich bleibe zu Hause, weil ich krank bin."},{"id":"d","texte":"Ich bleibe zu Hause, weil bin ich krank."}],"multiple":false},{"enonce":"Complète : « Bien que je sois fatigué, je vais au cinéma. »","aide":"On va au cinéma malgré la fatigue.","type":"trous","segments":[0," ich müde bin, gehe ich ins Kino."],"banque":["Damit","Weil","Bevor","Obwohl"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**denn** est une conjonction de coordination : l’ordre des mots ne change pas (*denn ich war krank*), contrairement à *weil*."},{"cle":{"type":"ordre","ids":["a","d","e","c","b"]},"explication":"**…, weil ich gestern lange gearbeitet habe.** Au temps composé, c’est l’auxiliaire conjugué (*habe*) qui est le dernier mot."},{"cle":{"type":"zone","ids":["m16"]},"explication":"**blieb** : la subordonnée occupe la première place, donc le verbe de la principale est deuxième, avant son sujet *ich*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**…, weil ich krank bin.** *weil* exige le verbe à la fin ; *denn* garde l’ordre ordinaire : *denn ich bin krank*."},{"cle":{"type":"trous","trous":[["obwohl"]]},"affichage":"Obwohl","explication":"**Obwohl ich müde bin, gehe ich ins Kino.** *obwohl* = bien que, et il envoie le verbe à la fin."}]$ex$::jsonb),
  ('e7990467-27c6-5852-a4fe-951d3d10117e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les voisins de la rue","competence":"comprendre-langue","situation":"Dans sa rue, Clara présente ses voisins. Elle les décrit avec de petites phrases relatives.","documents":[{"id":"nachbarn","type":"texte","genre":"recit","titre":"Unsere Straße","blocs":["Hier wohnt Herr Maier, der Klavier spielt. Gegenüber wohnt Frau Koch, die jeden Morgen Zeitung liest. Dort steht das Haus, das ganz neu ist."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif qui reprend « Frau Koch ».","aide":"Le pronom suit la virgule qui vient après le nom de la voisine.","type":"zone","document":"nachbarn","multiple":false},{"enonce":"Pourquoi Clara emploie-t-elle « der » dans « Herr Maier, der Klavier spielt » ?","aide":"Pense au genre de Herr Maier et à la fonction du pronom devant « spielt ».","type":"choix","options":[{"id":"a","texte":"Herr Maier est au datif dans la phrase"},{"id":"b","texte":"Klavier est un nom masculin placé après le verbe"},{"id":"c","texte":"L’antécédent est masculin et le pronom est sujet"},{"id":"d","texte":"Le verbe spielt exige toujours le mot der"}],"multiple":false},{"enonce":"Complète : « Là-bas se trouve la maison qui est toute neuve. »","aide":"L’antécédent est « das Haus », neutre, sujet de la relative.","type":"trous","segments":["Dort steht das Haus, ",0," ganz neu ist."],"banque":["die","der","den","das"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**die** : l’antécédent *Frau Koch* est féminin, et il est sujet de *liest* (nominatif)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le pronom prend le **genre de l’antécédent** (masculin) et le **cas de sa fonction** (sujet, nominatif) : **der**."},{"cle":{"type":"trous","trous":[["das"]]},"affichage":"das","explication":"**das** : *Haus* est neutre et sujet de *ist* (nominatif neutre : das)."}]$ex$::jsonb),
  ('e7990467-27c6-5852-a4fe-951d3d10117e'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le voisin dont tout le monde parle","competence":"manier-langue","situation":"Jule décrit sa famille de voisins. Chaque relative a son propre cas : prends le temps de chercher la fonction du pronom.","documents":[{"id":"nachbar","type":"texte","genre":"recit","titre":"Mein Nachbar","blocs":["Mein Nachbar ist ein Mann, den alle mögen. Seine Frau ist eine Lehrerin, der ich oft helfe. Ihre Kinder, die sehr laut sind, spielen im Garten. Sie haben einen Hund, mit dem ich gern spazieren gehe."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif au datif féminin : la voisine à qui Jule rend service.","aide":"Le verbe helfen est suivi du datif ; l’antécédent est féminin.","type":"zone","document":"nachbar","multiple":false},{"enonce":"Associe chaque relative à la fonction de son pronom.","aide":"Demande-toi quelle fonction le pronom a DANS la relative.","type":"association","gauche":[{"id":"g0","texte":"den alle mögen"},{"id":"g1","texte":"der ich oft helfe"},{"id":"g2","texte":"die sehr laut sind"},{"id":"g3","texte":"mit dem ich spazieren gehe"}],"droite":[{"id":"d0","texte":"après la préposition mit (datif)"},{"id":"d1","texte":"complément d’objet indirect (datif)"},{"id":"d2","texte":"complément d’objet direct (accusatif)"},{"id":"d3","texte":"sujet (nominatif pluriel)"}]},{"enonce":"Complète : « C’est l’amie à qui je donne le livre, et l’ami avec qui je voyage. »","aide":"Datif féminin pour la première, datif masculin (après mit) pour la seconde.","type":"trous","segments":["Das ist die Freundin, ",0," ich das Buch gebe, und der Freund, mit ",1," ich fahre."],"banque":["dem","den","die","der"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**der** : *Lehrerin* est féminin et *helfen* se construit avec le datif, donc datif féminin = *der*."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**den** = COD (acc. masc.), **der** = COI (dat. fém.), **die** = sujet (pluriel), **dem** = datif imposé par *mit*."},{"cle":{"type":"trous","trous":[["der"],["dem"]]},"affichage":"der · dem","explication":"**der** (datif féminin : on donne à *die Freundin*) et **dem** (datif masculin, imposé par *mit*)."}]$ex$::jsonb),
  ('e7990467-27c6-5852-a4fe-951d3d10117e'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le sac trouvé à l’école","competence":"raisonner","situation":"Un élève a trouvé un sac à dos dans la cour. Une note d’information du secrétariat explique ce qu’il faut faire.","documents":[{"id":"fund","type":"texte","genre":"article","titre":"Fundsache","blocs":["Ein Schüler hat gestern einen Rucksack gefunden, dessen Besitzer unbekannt ist. Die Lehrerin, deren Büro neben dem Eingang liegt, bewahrt ihn auf. Alles, was im Rucksack ist, steht auf einer Liste. Der Schüler kam zu spät, was die Lehrerin geärgert hat."],"source":"Note écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux pronoms relatifs au génitif.","aide":"Ils expriment l’appartenance : « dont le propriétaire », « dont le bureau ».","type":"zone","document":"fund","multiple":true},{"enonce":"Pourquoi écrit-on « Alles, was im Rucksack ist » et non « Alles, das… » ?","aide":"Pense à « alles », « nichts », « etwas ».","type":"choix","options":[{"id":"a","texte":"Après un pluriel, was remplace toujours das"},{"id":"b","texte":"Rucksack est masculin, donc il faut un autre pronom"},{"id":"c","texte":"Après alles, nichts ou etwas, le relatif est was"},{"id":"d","texte":"Das ne s’emploie jamais dans une proposition relative"}],"multiple":false},{"enonce":"Touche le « was » qui reprend toute la proposition précédente (« Der Schüler kam zu spät »).","aide":"Un seul des deux « was » reprend une phrase entière plutôt qu’un mot comme « alles ».","type":"zone","document":"fund","multiple":false},{"enonce":"Remets en ordre la relative : « Der Mann, … » (« dont la voiture est en panne »).","aide":"Après dessen, le nom n’a pas d’article ; le verbe va à la fin.","type":"ordre","items":[{"id":"a","texte":"kaputt"},{"id":"b","texte":"Auto"},{"id":"c","texte":"ist"},{"id":"d","texte":"dessen"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m13"]},"explication":"**dessen** (masculin) et **deren** (féminin) sont au génitif : « dont le… ». Le nom qui suit n’a pas d’article."},{"cle":{"type":"choix","ids":["c"]},"explication":"Après **alles, nichts, etwas, viel, wenig**, le pronom relatif est **was**."},{"cle":{"type":"zone","ids":["m36"]},"explication":"**was** (après « zu spät, ») reprend toute la phrase précédente : il signifie « ce qui »."},{"cle":{"type":"ordre","ids":["d","b","a","c"]},"explication":"**Der Mann, dessen Auto kaputt ist** : *dessen* + nom sans article, et le verbe conjugué ferme la relative."}]$ex$::jsonb),
  ('4cbcec13-85fc-58b3-a2bc-f580a95120d6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une ville en travaux","competence":"comprendre-langue","situation":"Un journal local décrit tout ce qui se passe dans la ville cet été. Lis l’article et repère le passif.","documents":[{"id":"stadt","type":"texte","genre":"article","titre":"Bei uns wird gebaut","blocs":["In unserer Stadt wird viel gebaut. Das Schwimmbad wird renoviert. Im Sommer wurde die Brücke repariert. Die neue Schule ist schon gebaut worden."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux formes de « werden » au présent qui construisent un passif d’action.","aide":"Cherche l’auxiliaire werden conjugué à la 3e personne du singulier.","type":"zone","document":"stadt","multiple":true},{"enonce":"Que dit la phrase « Die neue Schule ist schon gebaut worden » ?","aide":"Au parfait du passif, on a « ist … worden » et le mot « schon ».","type":"choix","options":[{"id":"a","texte":"L’école neuve a déjà été construite"},{"id":"b","texte":"L’école neuve n’a pas encore été construite"},{"id":"c","texte":"L’école neuve est en train d’être construite"},{"id":"d","texte":"L’école neuve sera bientôt construite"}],"multiple":false},{"enonce":"Complète au prétérit passif : « La maison fut construite. »","aide":"Au prétérit, werden devient « wurde ».","type":"trous","segments":["Das Haus ",0," gebaut."],"banque":["worden","ist","wurde","wird"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m8"]},"explication":"**wird** (deux fois) est le présent de *werden* : *wird gebaut*, *wird renoviert*. *wurde* est au prétérit et *ist … worden* au parfait."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le parfait du passif (**ist gebaut worden**) dit que l’action est faite : l’école a déjà été construite."},{"cle":{"type":"trous","trous":[["wurde"]]},"affichage":"wurde","explication":"**Das Haus wurde gebaut.** Prétérit du passif : *wurde* + participe passé."}]$ex$::jsonb),
  ('4cbcec13-85fc-58b3-a2bc-f580a95120d6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui l’a fait ? Von ou durch","competence":"analyser-texte","situation":"Trois courtes nouvelles locales utilisent le passif. À chaque fois, une préposition introduit « celui qui fait » ou « ce par quoi ».","documents":[{"id":"meldungen","type":"texte","genre":"article","titre":"Drei Meldungen","blocs":["Das Märchen wurde von den Brüdern Grimm gesammelt.","Die Brücke wurde durch das Hochwasser zerstört.","Heute wird in der Aula getanzt."],"source":"Articles écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui introduit une personne agissante : les frères Grimm.","aide":"C’est une préposition suivie du datif.","type":"zone","document":"meldungen","multiple":false},{"enonce":"Que signifie la troisième phrase « Heute wird in der Aula getanzt » ?","aide":"Il n’y a pas de complément d’objet, donc pas de sujet « réel ».","type":"choix","options":[{"id":"a","texte":"Aujourd’hui, on danse dans l’aula"},{"id":"b","texte":"Aujourd’hui, l’aula est dansée"},{"id":"c","texte":"Aujourd’hui, il a dansé dans l’aula"},{"id":"d","texte":"Aujourd’hui, on va construire l’aula"}],"multiple":false},{"enonce":"Touche la préposition qui introduit un moyen ou une cause naturelle : le Hochwasser, la crue.","aide":"C’est une préposition suivie de l’accusatif.","type":"zone","document":"meldungen","multiple":false},{"enonce":"Remets en ordre : « Le travail doit être fait aujourd’hui. » La phrase commence par Die Arbeit.","aide":"Le modal est conjugué, le passif passe à l’infinitif : participe + werden à la fin.","type":"ordre","items":[{"id":"a","texte":"muss"},{"id":"b","texte":"heute"},{"id":"c","texte":"gemacht"},{"id":"d","texte":"Die Arbeit"},{"id":"e","texte":"werden"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**von** + datif introduit l’agent quand c’est une personne ou une force qui agit : *von den Brüdern Grimm*."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est un **passif impersonnel** : le verbe *tanzen* n’a pas de COD, et la phrase se traduit par « on danse »."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**durch** + accusatif introduit un moyen, un intermédiaire ou un événement : *durch das Hochwasser*."},{"cle":{"type":"ordre","ids":["d","a","b","c","e"]},"explication":"**Die Arbeit muss heute gemacht werden.** Avec un modal, le passif est à l’infinitif : *gemacht werden*, tout à la fin."}]$ex$::jsonb),
  ('4cbcec13-85fc-58b3-a2bc-f580a95120d6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La rue fermée : action ou résultat ?","competence":"raisonner","situation":"Anna et Jonas croisent une rue fermée pour travaux. Leur conversation oppose ce qui se passe et ce qui est acquis.","documents":[{"id":"strasse","type":"dialogue","modele":"sms","titre":"Gesperrte Straße","participants":[{"nom":"Anna","emoji":"👧","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anna","texte":"Warum ist die Straße gesperrt?"},{"qui":"Jonas","texte":"Sie wird gerade repariert."},{"qui":"Anna","texte":"Und wann ist das fertig?"},{"qui":"Jonas","texte":"Morgen. Dann ist sie wieder geöffnet. Gestern wurde sie noch von der Stadt geprüft."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes qui décrivent un résultat acquis (passif d’état, avec « ist »).","aide":"Le passif d’état se construit avec sein + participe : cherche « ist … ».","type":"zone","document":"strasse","multiple":true},{"enonce":"Range chaque phrase selon qu’elle décrit une action en cours ou un résultat acquis.","aide":"Werden + participe : action. Sein + participe : résultat.","type":"categories","categories":[{"id":"c0","texte":"Passif d’action (le film)"},{"id":"c1","texte":"Passif d’état (la photo)"}],"items":[{"id":"i0","texte":"Die Straße wird repariert."},{"id":"i1","texte":"Das Haus ist gebaut."},{"id":"i2","texte":"Die Tür ist geöffnet."},{"id":"i3","texte":"Das Haus wird gebaut."}]},{"enonce":"Complète au parfait du passif : « La rue a déjà été réparée. »","aide":"Au parfait du passif, le participe de werden perd son ge-.","type":"trous","segments":["Die Straße ist schon repariert ",0,"."],"banque":["worden","werden","wurde","geworden"]},{"enonce":"Mets « Man repariert die Straße » au passif présent.","aide":"Le COD devient sujet ; werden est conjugué, le participe est à la fin.","type":"ordre","items":[{"id":"a","texte":"repariert"},{"id":"b","texte":"Die Straße"},{"id":"c","texte":"wird"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m19"]},"explication":"**gesperrt** et **geöffnet** suivent « ist » : ils décrivent un état. À l’inverse, *wird repariert* décrit une action en cours."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"**werden + participe** montre l’action en train de se faire ; **sein + participe** montre le résultat, comme une photographie."},{"cle":{"type":"trous","trous":[["worden"]]},"affichage":"worden","explication":"**Die Straße ist schon repariert worden.** Au passif, le participe de *werden* est *worden* (et non *geworden*, réservé à « devenir »)."},{"cle":{"type":"ordre","ids":["b","c","a"]},"explication":"**Die Straße wird repariert.** Le complément d’objet du tour actif (*die Straße*) devient le sujet du passif."}]$ex$::jsonb),
  ('a1ca1f57-7faa-533b-b303-0f23562e46f0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets de l’été","competence":"comprendre-langue","situation":"Mia et Ben parlent de leurs vacances. Observe les petits « zu » placés devant leurs verbes.","documents":[{"id":"sommer","type":"dialogue","modele":"sms","titre":"Was machst du im Sommer?","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Was hast du im Sommer vor?"},{"qui":"Ben","texte":"Ich habe vor, nach Italien zu fahren."},{"qui":"Mia","texte":"Super! Ich versuche, einen Ferienjob zu finden."},{"qui":"Ben","texte":"Hast du Lust, mit mir zu fahren?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois « zu » de la conversation.","aide":"Le petit mot zu se place juste devant l’infinitif.","type":"zone","document":"sommer","multiple":true},{"enonce":"Range chaque verbe selon qu’il demande « zu » devant l’infinitif ou non.","aide":"Les modaux, les verbes de mouvement et sehen / hören / lassen refusent zu.","type":"categories","categories":[{"id":"c0","texte":"Infinitif avec zu"},{"id":"c1","texte":"Infinitif sans zu"}],"items":[{"id":"i0","texte":"hören"},{"id":"i1","texte":"können"},{"id":"i2","texte":"hoffen"},{"id":"i3","texte":"versuchen"},{"id":"i4","texte":"gehen"},{"id":"i5","texte":"vergessen"}]},{"enonce":"Complète : « As-tu envie d’aller au cinéma ? »","aide":"Après « Lust haben », l’infinitif prend zu.","type":"trous","segments":["Hast du Lust, ins Kino ",0," gehen?"],"banque":["ohne","um","zu","zum"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m18","m25"]},"explication":"Les trois **zu** se trouvent devant *fahren*, *finden*, *fahren* : après *vorhaben*, *versuchen* et *Lust haben*, l’infinitif prend zu."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**versuchen, hoffen, vergessen** appellent *zu*. Les **modaux** (*können*), les verbes de mouvement (*gehen*) et *hören* l’excluent."},{"cle":{"type":"trous","trous":[["zu"]]},"affichage":"zu","explication":"**Hast du Lust, ins Kino zu gehen ?** *zu* se place juste devant l’infinitif, en fin de groupe."}]$ex$::jsonb),
  ('a1ca1f57-7faa-533b-b303-0f23562e46f0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Lea apprend l’espagnol","competence":"analyser-texte","situation":"Un petit article présente une lycéenne qui prépare son avenir. Les groupes infinitifs expriment un but, une privation ou une substitution.","documents":[{"id":"lea","type":"texte","genre":"article","titre":"Leas Plan","blocs":["Lea lernt Spanisch, um in Madrid zu arbeiten. Ihre Mutter bezahlt den Kurs, damit Lea eine gute Lehrerin hat. Statt zu schlafen, übt sie jeden Morgen."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction du but employée parce que les deux propositions n’ont pas le même sujet.","aide":"Le sujet de la première proposition est la mère ; celui de la seconde est Lea.","type":"zone","document":"lea","multiple":false},{"enonce":"Pourquoi ne peut-on pas écrire « …, um Lea eine gute Lehrerin zu haben » ?","aide":"Qui paie le cours ? Et qui doit avoir une bonne professeure ?","type":"choix","options":[{"id":"a","texte":"Le verbe haben ne se met jamais à l’infinitif"},{"id":"b","texte":"Lehrerin est un nom qui ne se déclinerait pas"},{"id":"c","texte":"Um… zu exprime toujours la cause, jamais le but"},{"id":"d","texte":"Les deux propositions n’ont pas le même sujet"}],"multiple":false},{"enonce":"Associe chaque groupe infinitif à ce qu’il exprime.","aide":"Pense aux traductions : « pour », « sans », « au lieu de ».","type":"association","gauche":[{"id":"g0","texte":"um… zu"},{"id":"g1","texte":"ohne… zu"},{"id":"g2","texte":"statt… zu"}],"droite":[{"id":"d0","texte":"la substitution (au lieu de)"},{"id":"d1","texte":"le but"},{"id":"d2","texte":"la privation (sans faire)"}]},{"enonce":"Remets en ordre la fin de la phrase « Ich lerne Deutsch, … » (« pour étudier à Berlin »).","aide":"Le groupe est introduit par um ; zu se place juste devant l’infinitif final.","type":"ordre","items":[{"id":"a","texte":"in Berlin"},{"id":"b","texte":"um"},{"id":"c","texte":"studieren"},{"id":"d","texte":"zu"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**damit** : avec deux sujets différents (*die Mutter* / *Lea*), on ne peut pas employer *um… zu*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**um… zu** exige le **même sujet** dans les deux propositions. Si le sujet change, on emploie **damit**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**um… zu** = pour (but), **ohne… zu** = sans, **statt… zu** = au lieu de. Tous trois exigent une virgule."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**…, um in Berlin zu studieren.** *um* ouvre le groupe, *zu* précède l’infinitif qui le ferme."}]$ex$::jsonb),
  ('a1ca1f57-7faa-533b-b303-0f23562e46f0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La liste de choses à faire","competence":"manier-langue","situation":"Sarah a écrit un pense-bête pour sa journée. Elle y mélange infinitifs avec zu, sans zu, et tournures plus soutenues.","documents":[{"id":"zettel","type":"texte","genre":"consigne","titre":"Sarahs Zettel","blocs":["Heute habe ich viel zu tun: Ich muss früh aufstehen. Ich vergesse nicht, Oma anzurufen. Danach habe ich vor, im Supermarkt einzukaufen. Die Hausaufgaben sind bis morgen zu machen."],"source":"Pense-bête écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux verbes à préverbe séparable dans lesquels zu s’est glissé au milieu du mot.","aide":"Le zu s’intercale entre le préverbe (an-, ein-) et le radical.","type":"zone","document":"zettel","multiple":true},{"enonce":"Que signifie « Die Hausaufgaben sind bis morgen zu machen » ?","aide":"Sein + zu + infinitif a une valeur passive d’obligation ou de possibilité.","type":"choix","options":[{"id":"a","texte":"Les devoirs doivent être faits d’ici demain"},{"id":"b","texte":"Les devoirs ont été faits hier soir"},{"id":"c","texte":"Les devoirs sont faits par quelqu’un d’autre"},{"id":"d","texte":"Les devoirs ne sont pas à faire"}],"multiple":false},{"enonce":"Complète : « Je n’oublie pas d’appeler Oma. » (anrufen)","aide":"Avec un préverbe séparable, zu s’intercale entre le préverbe et le radical, en un seul mot.","type":"trous","segments":["Ich vergesse nicht, Oma ",0,"."],"banque":["anzurufen","zu anrufen","anrufen","zuanrufen"]},{"enonce":"Remets en ordre la fin de la phrase « Er ging weg, … » (« sans rien dire »).","aide":"Le groupe commence par ohne et se termine par l’infinitif précédé de zu.","type":"ordre","items":[{"id":"a","texte":"ohne"},{"id":"b","texte":"zu"},{"id":"c","texte":"sagen"},{"id":"d","texte":"etwas"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m21"]},"explication":"**anzurufen** et **einzukaufen** : avec un préverbe séparable, *zu* s’insère entre le préverbe et le radical, en un seul mot. *aufstehen* n’a pas de zu après un modal."},{"cle":{"type":"choix","ids":["a"]},"explication":"**sein + zu + infinitif** a une valeur passive : « doit être fait »."},{"cle":{"type":"trous","trous":[["anzurufen"]]},"affichage":"anzurufen","explication":"**anzurufen** : an + zu + rufen, en un seul mot. Le groupe infinitif ferme la phrase."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"**Er ging weg, ohne etwas zu sagen.** *ohne… zu* exprime la privation, avec une virgule devant."}]$ex$::jsonb),
  ('f5d1d5c8-3cf2-5b7e-be2f-45f044b72e95'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans la chambre de Lisa","competence":"manier-langue","situation":"Lisa range sa chambre et dresse la liste de ce qu’elle y trouve. En allemand, chaque nom a son article : der, die ou das.","documents":[{"id":"zimmer","type":"tableau","titre":"Lisas Zimmer","colonnes":["Wort"],"lignes":[["Tisch"],["Lampe"],["Stuhl"],["Kätzchen"],["Tür"],["Buch"]],"enteteLignes":false,"source":"Liste écrite pour l’exercice"}],"questions":[{"enonce":"Range chaque mot de la liste de Lisa avec son article.","aide":"Le diminutif en -chen est neutre ; Lampe et Tür sont féminins.","type":"categories","categories":[{"id":"c0","texte":"der"},{"id":"c1","texte":"die"},{"id":"c2","texte":"das"}],"items":[{"id":"i0","texte":"Tür"},{"id":"i1","texte":"Stuhl"},{"id":"i2","texte":"Buch"},{"id":"i3","texte":"Lampe"},{"id":"i4","texte":"Tisch"},{"id":"i5","texte":"Kätzchen"}]},{"enonce":"Touche le mot de la liste qui est neutre à cause de sa terminaison -chen.","aide":"Cherche un diminutif : un petit animal.","type":"zone","document":"zimmer","multiple":false},{"enonce":"Lisa écrit « die Stühle ». Pourquoi l’article est-il « die » alors que « der Stuhl » est masculin ?","aide":"Pense à la seule « simplification » de l’allemand.","type":"choix","options":[{"id":"a","texte":"Stühle est un nom féminin au singulier, comme Lampe"},{"id":"b","texte":"Die est le pluriel des seuls noms de genre masculin"},{"id":"c","texte":"Au pluriel, l’article défini est die pour les trois genres"},{"id":"d","texte":"Le tréma sur le ü rend automatiquement le mot féminin"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c1","i4":"c0","i5":"c2"}},"explication":"**der Tisch, der Stuhl** (masculins), **die Lampe, die Tür** (féminins), **das Kätzchen, das Buch** (neutres)."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"**Kätzchen** est neutre : tous les diminutifs en *-chen* et *-lein* sont neutres, même si le mot désigne un être vivant."},{"cle":{"type":"choix","ids":["c"]},"explication":"Au pluriel, l’article défini est **die** pour les trois genres : *die Stühle, die Lampen, die Bücher*."}]$ex$::jsonb),
  ('f5d1d5c8-3cf2-5b7e-be2f-45f044b72e95'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Les mots du quotidien","competence":"manier-langue","situation":"Dans son cahier, Mehmet a noté huit mots d’allemand pour s’entraîner à deviner le genre grâce à leur terminaison ou à leur sens.","documents":[{"id":"woerter","type":"tableau","titre":"Acht Wörter","colonnes":["Wort","Mein Tipp"],"lignes":[["Zeitung","terminaison -ung"],["Freiheit","terminaison -heit"],["Lehrer","terminaison -er"],["Frühling","une saison"],["Medikament","terminaison -ment"],["Mädchen","terminaison -chen"],["Bäckerei","terminaison -ei"],["Montag","un jour"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots du tableau qui sont féminins.","aide":"Les terminaisons -ung, -heit et -ei signalent le féminin.","type":"zone","document":"woerter","multiple":true},{"enonce":"Complète avec le bon article : « La liberté est importante. Le printemps est beau. »","aide":"Freiheit finit par -heit ; les saisons sont masculines.","type":"trous","segments":[0," Freiheit ist wichtig. ",1," Frühling ist schön."],"banque":["Das","Die","Der"]},{"enonce":"Comment dit-on « Il est professeur » ?","aide":"Après sein, un métier s’emploie sans article.","type":"choix","options":[{"id":"a","texte":"Er ist Lehrer."},{"id":"b","texte":"Er ist einen Lehrer."},{"id":"c","texte":"Er ist der Lehrer."},{"id":"d","texte":"Er ist ein Lehrer."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r1c0","r6c0"]},"explication":"**Zeitung, Freiheit, Bäckerei** sont féminins (*die*). Les noms en -ung, -heit, -keit, -schaft, -ion, -ei, -ie sont féminins."},{"cle":{"type":"trous","trous":[["die"],["der"]]},"affichage":"Die · Der","explication":"**Die Freiheit** (féminin, -heit) et **der Frühling** (masculin, une saison)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Er ist Lehrer.** Après *sein* ou *werden*, un métier s’emploie sans article, contrairement au français « il est un… »."}]$ex$::jsonb),
  ('f5d1d5c8-3cf2-5b7e-be2f-45f044b72e95'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une famille à Vienne","competence":"raisonner","situation":"Nina rend visite à son cousin Karl en Autriche. Il lui présente sa famille. Ils jouent aussi à deviner le genre des mots.","documents":[{"id":"familie","type":"dialogue","modele":"sms","titre":"Wer ist das?","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Karl","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Wer ist das?"},{"qui":"Karl","texte":"Das ist mein Onkel. Er ist Lehrer."},{"qui":"Nina","texte":"Und das?"},{"qui":"Karl","texte":"Das sind meine Cousinen. Sie wohnen in Österreich."}],"source":"Messages écrits pour l’exercice"},{"id":"regeln","type":"tableau","titre":"Drei Tipps","colonnes":["Wort","Hinweis"],"lignes":[["Zeitung","Endung -ung"],["Mädchen","Endung -chen"],["Montag","Wochentag"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui est au pluriel parce qu’il s’accorde avec « meine Cousinen », et non avec « das ».","aide":"Cherche le verbe sein conjugué à la 3e personne du pluriel.","type":"zone","document":"familie","multiple":false},{"enonce":"Quel est le rôle de « Das » dans « Das ist mein Onkel » ?","aide":"Onkel est masculin : l’article neutre ne pourrait pas s’accorder avec lui.","type":"choix","options":[{"id":"a","texte":"Pronom personnel qui remplace le groupe mein Onkel"},{"id":"b","texte":"Démonstratif invariable qui désigne une personne ou une chose"},{"id":"c","texte":"Article défini neutre placé devant le nom Onkel"},{"id":"d","texte":"Conjonction de subordination, tout comme le mot dass"}],"multiple":false},{"enonce":"Associe chaque mot du tableau de Karl au genre que sa terminaison ou son sens annonce.","aide":"Relis les trois indices du tableau : une terminaison, un diminutif, un jour.","type":"association","gauche":[{"id":"g0","texte":"die Zeitung"},{"id":"g1","texte":"das Mädchen"},{"id":"g2","texte":"der Montag"}],"droite":[{"id":"d0","texte":"neutre (-chen)"},{"id":"d1","texte":"féminin (-ung)"},{"id":"d2","texte":"masculin (jour)"}]},{"enonce":"Dans « Sie wohnen in Österreich », pourquoi le nom du pays n’a-t-il pas d’article ?","aide":"Pense à « nach Deutschland », « in Frankreich ».","type":"choix","options":[{"id":"a","texte":"La plupart des noms de pays s’emploient sans article"},{"id":"b","texte":"Österreich est un nom pluriel, donc sans article"},{"id":"c","texte":"Les noms de pays sont toujours masculins"},{"id":"d","texte":"Après in, un nom ne prend jamais d’article"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**sind** : dans *Das sind meine Cousinen*, *das* est invariable et le verbe s’accorde avec le groupe qui suit (pluriel)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Das** est ici un démonstratif invariable (« ça, c’est… ») : il ne s’accorde ni avec le genre, ni avec le nombre de ce qui suit."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**die Zeitung** (-ung : féminin), **das Mädchen** (-chen : neutre), **der Montag** (les jours sont masculins)."},{"cle":{"type":"choix","ids":["a"]},"explication":"La plupart des **noms de pays** (*Österreich, Deutschland, Frankreich*) s’emploient **sans article** : *Sie wohnen in Österreich.*"}]$ex$::jsonb),
  ('dd419f5e-9d57-5cb8-b619-439a87c6f6ef'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une visite au zoo","competence":"comprendre-langue","situation":"Tim et Zoé visitent le zoo. Observe les articles qui accompagnent les noms complément d’objet direct.","documents":[{"id":"zoo","type":"dialogue","modele":"sms","titre":"Im Zoo","participants":[{"nom":"Tim","emoji":"👦","cote":"gauche"},{"nom":"Zoé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tim","texte":"Im Zoo sehe ich einen Hund, eine Katze und ein Pferd."},{"qui":"Zoé","texte":"Und ich sehe den Vogel dort."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux articles qui montrent un nom masculin à l’accusatif.","aide":"Le masculin est le seul genre qui change entre le nominatif et l’accusatif.","type":"zone","document":"zoo","multiple":true},{"enonce":"Complète : « Je vois la table. » (masculin : der Tisch)","aide":"Le COD est à l’accusatif, et Tisch est masculin.","type":"trous","segments":["Ich sehe ",0," Tisch."],"banque":["des","der","dem","den"]},{"enonce":"Quel genre est le seul à changer entre le nominatif et l’accusatif ?","aide":"Compare der / den, ein / einen.","type":"choix","options":[{"id":"a","texte":"Le masculin"},{"id":"b","texte":"Le féminin"},{"id":"c","texte":"Le neutre"},{"id":"d","texte":"Le pluriel"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m14"]},"explication":"**einen** (devant *Hund*) et **den** (devant *Vogel*) : seuls les masculins changent à l’accusatif (*ein → einen*, *der → den*)."},{"cle":{"type":"trous","trous":[["den"]]},"affichage":"den","explication":"**Ich sehe den Tisch.** Accusatif masculin : *der → den*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Le masculin seul** change : *der → den*, *ein → einen*. Féminin, neutre et pluriel gardent la même forme."}]$ex$::jsonb),
  ('dd419f5e-9d57-5cb8-b619-439a87c6f6ef'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre pleine de cas","competence":"manier-langue","situation":"Une lettre de Lena à son frère mélange les quatre cas. À toi de les repérer et de justifier chaque terminaison.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Lenas Brief","blocs":["Ich schreibe meinem Bruder einen Brief. Der Brief liegt auf dem Tisch. Das ist das Auto des Vaters. Ich gebe jedem Kind ein Geschenk. Mit den Kindern spiele ich."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’article au génitif, qui exprime la possession.","aide":"Cherche le complément du nom : « la voiture du père ».","type":"zone","document":"brief","multiple":false},{"enonce":"Complète la dernière phrase : « Je joue avec les enfants. »","aide":"Au datif pluriel, le nom lui-même prend une marque en plus.","type":"trous","segments":["Mit den Kinder",0," spiele ich."],"banque":["s","n","e","er"]},{"enonce":"Touche le possessif au datif : Lena écrit à qui ?","aide":"Il se décline comme « einem » devant un nom masculin.","type":"zone","document":"brief","multiple":false},{"enonce":"Associe chaque cas à sa fonction principale.","aide":"Retrouve dans la lettre : Ich (sujet), einen Brief, meinem Bruder, des Vaters.","type":"association","gauche":[{"id":"g0","texte":"Nominatif"},{"id":"g1","texte":"Accusatif"},{"id":"g2","texte":"Datif"},{"id":"g3","texte":"Génitif"}],"droite":[{"id":"d0","texte":"le complément d’objet direct"},{"id":"d1","texte":"le sujet"},{"id":"d2","texte":"le complément d’objet indirect"},{"id":"d3","texte":"le complément du nom"}]}]}$ex$::jsonb,
