   $ex${"titre":"Le vélo de Karl","competence":"raisonner","situation":"Mara complète le tableau de l’article défini avant de discuter du vélo de son cousin. Un bon tableau, c’est la moitié du travail.","documents":[{"id":"tab","type":"tableau","titre":"Der bestimmte Artikel","colonnes":["Fall","Maskulin","Feminin","Neutrum","Plural"],"lignes":[["Nominativ","der","die","das","die"],["Akkusativ","?","die","das","die"],["Dativ","dem","?","dem","den"],["Genitiv","des","der","des","der"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"rad","type":"dialogue","modele":"sms","titre":"Das Fahrrad","participants":[{"nom":"Mara","emoji":"👧","cote":"gauche"},{"nom":"Ole","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mara","texte":"Wem gehört das Fahrrad?"},{"qui":"Ole","texte":"Das Fahrrad gehört meinem Bruder. Er fährt damit zu seinen Freunden."},{"qui":"Mara","texte":"Und das Auto vor dem Haus?"},{"qui":"Ole","texte":"Das ist das Auto meines Vaters."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Complète le tableau : accusatif masculin et datif féminin.","aide":"Le masculin est le seul genre qui change entre nominatif et accusatif.","type":"trous","segments":["Accusatif masculin : ",0," — datif féminin : ",1],"banque":["des","den","der","dem"]},{"enonce":"Touche le possessif au génitif dans la conversation.","aide":"Il suit « das Auto » et marque la possession.","type":"zone","document":"rad","multiple":false},{"enonce":"Pourquoi Ole écrit-il « meinem Bruder » et non « meinen Bruder » dans « Das Fahrrad gehört meinem Bruder » ?","aide":"Cherche le cas qui suit le verbe gehören.","type":"choix","options":[{"id":"a","texte":"Bruder est un nom au pluriel"},{"id":"b","texte":"Le sujet est toujours au datif"},{"id":"c","texte":"Gehören se construit avec le datif"},{"id":"d","texte":"Meinen est réservé au génitif"}],"multiple":false},{"enonce":"Complète : « Il roule vers ses amis. » (Freund + terminaison)","aide":"Au datif pluriel, le nom prend un -n supplémentaire ; Freund est déjà au pluriel avec -e.","type":"trous","segments":["Er fährt zu seinen Freund",0,"."],"banque":["er","en","s","e"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["den"],["der"]]},"affichage":"den · der","explication":"**den** (accusatif masculin) et **der** (datif féminin : *der Frau*)."},{"cle":{"type":"zone","ids":["m25"]},"explication":"**meines** : génitif masculin de *mein* (*meines Vaters*), avec -es sur le possessif et -s sur le nom."},{"cle":{"type":"choix","ids":["c"]},"explication":"**gehören** exige le datif : *meinem Bruder* (datif masculin de *mein*)."},{"cle":{"type":"trous","trous":[["en"]]},"affichage":"en","explication":"**Freunden** : pluriel *Freunde* + **-n** au datif pluriel."}]$ex$::jsonb),
