   $ex${"titre":"Où est l’objet ?","competence":"comprendre-langue","situation":"Julia cherche plusieurs objets dans la maison. Max lui répond en les reprenant par un pronom.","documents":[{"id":"suche","type":"dialogue","modele":"sms","titre":"Wo ist …?","participants":[{"nom":"Julia","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Julia","texte":"Wo ist der Schlüssel?"},{"qui":"Max","texte":"Er liegt auf dem Tisch."},{"qui":"Julia","texte":"Und wo ist die Lampe?"},{"qui":"Max","texte":"Sie steht im Zimmer. Das Buch ist auch dort. Es ist neu."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom qui remplace « der Schlüssel ».","aide":"Un pronom reprend le genre grammatical du nom, pas son sens.","type":"zone","document":"suche","multiple":false},{"enonce":"Complète : « La table est vieille. Elle est brune. » (der Tisch)","aide":"En allemand, une table est « il ».","type":"trous","segments":["Der Tisch ist alt. ",0," ist braun."],"banque":["Ihn","Es","Sie","Er"]},{"enonce":"Quel pronom reprend « das Buch » dans la conversation ?","aide":"Buch est neutre.","type":"choix","options":[{"id":"a","texte":"es"},{"id":"b","texte":"sie"},{"id":"c","texte":"er"},{"id":"d","texte":"ihn"}],"multiple":false}]}$ex$::jsonb,
