   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**diesen** : accusatif masculin de *dieser*, comme *den* pour *der*."},{"cle":{"type":"trous","trous":[["dieses"]]},"affichage":"dieses","explication":"**dieses Buch** : neutre, la terminaison est celle de l’article défini *das* → *-es*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**dieser** prend les terminaisons de l’article défini : *dieser, diesen, diesem, dieses*."}]$ex$::jsonb),
  ('233e32f0-3d00-5436-8186-f3679bbb5338'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"« Den kenne ich gut ! »","competence":"manier-langue","situation":"Anna et Ben parlent de leurs camarades. Dans la langue de tous les jours, on montre quelqu’un avec der, die, das.","documents":[{"id":"kennen2","type":"dialogue","modele":"sms","titre":"Wer ist Peter?","participants":[{"nom":"Anna","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anna","texte":"Kennst du Peter?"},{"qui":"Ben","texte":"Den kenne ich gut! Mit dem spiele ich Fußball."},{"qui":"Anna","texte":"Und Lea?"},{"qui":"Ben","texte":"Die kenne ich nicht. Aber von der habe ich viel gehört."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le démonstratif accentué à l’accusatif masculin qui reprend « Peter ».","aide":"Il ouvre la phrase de Ben, comme un « Lui, je le connais bien ! ».","type":"zone","document":"kennen2","multiple":false},{"enonce":"Pourquoi Ben dit-il « Mit dem spiele ich Fußball » et non « Mit den » ?","aide":"Repère la préposition et le genre de la personne.","type":"choix","options":[{"id":"a","texte":"Mit exige l’accusatif, et Peter est pluriel"},{"id":"b","texte":"Mit exige le datif, et Peter est masculin"},{"id":"c","texte":"Peter est neutre, donc dem est obligatoire"},{"id":"d","texte":"Dem est la forme du nominatif masculin"}],"multiple":false},{"enonce":"Touche les deux démonstratifs qui désignent Lea.","aide":"Un à l’accusatif féminin, l’autre au datif féminin après von.","type":"zone","document":"kennen2","multiple":true},{"enonce":"Complète : « Je ne connais pas les enfants. Je ne parle jamais avec eux. »","aide":"Le démonstratif au datif pluriel a une forme particulière.","type":"trous","segments":["Die Kinder kenne ich nicht. Mit ",0," spreche ich nie."],"banque":["dem","den","die","denen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**Den kenne ich gut !** : *den* est le démonstratif accentué, accusatif masculin ; il est en tête pour insister."},{"cle":{"type":"choix","ids":["b"]},"explication":"**mit** est suivi du datif, et le démonstratif masculin au datif est **dem**."},{"cle":{"type":"zone","ids":["m14","m20"]},"explication":"**Die** (accusatif féminin : « elle, je ne la connais pas ») et **der** (datif féminin après *von*) désignent Lea."},{"cle":{"type":"trous","trous":[["denen"]]},"affichage":"denen","explication":"**denen** : datif pluriel du démonstratif (comme du pronom relatif), imposé par *mit*."}]$ex$::jsonb),
  ('233e32f0-3d00-5436-8186-f3679bbb5338'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux amies, le même T-shirt","competence":"raisonner","situation":"Lea et Mia portent un T-shirt qui se ressemble beaucoup. Un petit article raconte leur journée, avec quelques démonstratifs plus fins.","documents":[{"id":"freundinnen","type":"texte","genre":"article","titre":"Zwei Freundinnen","blocs":["Zwei Freundinnen, Lea und Mia, tragen heute das gleiche T-Shirt. Sie wohnen in demselben Haus, im dritten Stock. Lea traf gestern Paul und dessen Schwester."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit que les deux T-shirts sont semblables, mais que ce sont deux exemplaires.","aide":"Il y a deux objets différents, de même modèle.","type":"zone","document":"freundinnen","multiple":false},{"enonce":"À qui appartient la sœur dans « Paul und dessen Schwester » ?","aide":"Dessen remplace un possessif ambigu et vise le nom juste avant.","type":"choix","options":[{"id":"a","texte":"À Lea, qui l’a rencontrée"},{"id":"b","texte":"À une personne non citée"},{"id":"c","texte":"À Mia, l’autre amie"},{"id":"d","texte":"À Paul, le dernier nom cité"}],"multiple":false},{"enonce":"Touche le mot qui dit qu’elles habitent dans la MÊME maison, un seul et unique bâtiment.","aide":"Il s’agit d’un seul objet, identique.","type":"zone","document":"freundinnen","multiple":false},{"enonce":"Associe chaque forme à ce qu’elle exprime.","aide":"Relis le texte : une maison, deux T-shirts, la sœur de Paul.","type":"association","gauche":[{"id":"g0","texte":"derselbe"},{"id":"g1","texte":"der gleiche"},{"id":"g2","texte":"dessen"},{"id":"g3","texte":"dieser"}],"droite":[{"id":"d0","texte":"démonstratif neutre de base"},{"id":"d1","texte":"semblable : deux objets"},{"id":"d2","texte":"possessif qui lève l’ambiguïté"},{"id":"d3","texte":"identique : un seul objet"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**gleiche** (*das gleiche T-Shirt*) : deux objets semblables."},{"cle":{"type":"choix","ids":["d"]},"explication":"**dessen** = « de celui-ci » : c’est la sœur de **Paul**, sans équivoque (alors que *seine Schwester* pourrait être ambigu)."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**demselben** (*in demselben Haus*) : un seul Haus, identique. *Derselbe* se décline sur ses deux morceaux."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"**derselbe** = même objet ; **der gleiche** = même modèle ; **dessen** = « de celui-ci » ; **dieser** = démonstratif de base."}]$ex$::jsonb),
  ('f04b8338-b125-5b3b-9800-005d4202fbc1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les affaires du vide-grenier","competence":"manier-langue","situation":"Samedi, le quartier de Hannah organise un vide-grenier. Une affiche annonce ce qu’on y trouvera, et Hannah veut repérer les pluriels.","documents":[{"id":"flohmarkt","type":"texte","genre":"article","titre":"Flohmarkt am Samstag","blocs":["Bei uns gibt es Bücher, Lampen, Stühle und Autos für Kinder. Kommt vorbei!"],"source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche le seul pluriel qui se termine par -s : c’est un mot emprunté.","aide":"Les mots empruntés prennent un -s ; les autres pluriels de l’affiche n’en ont pas.","type":"zone","document":"flohmarkt","multiple":false},{"enonce":"Associe chaque nom au singulier au pluriel qui figure sur l’affiche.","aide":"Retrouve le mot dans le texte et regarde sa terminaison.","type":"association","gauche":[{"id":"g0","texte":"das Buch"},{"id":"g1","texte":"die Lampe"},{"id":"g2","texte":"der Stuhl"},{"id":"g3","texte":"das Auto"}],"droite":[{"id":"d0","texte":"die Bücher"},{"id":"d1","texte":"die Lampen"},{"id":"d2","texte":"die Autos"},{"id":"d3","texte":"die Stühle"}]},{"enonce":"Complète : « Anna achète deux journaux. »","aide":"Presque tous les féminins prennent -n ou -en, sans inflexion.","type":"trous","segments":["Anna kauft zwei ",0,"."],"banque":["Zeitungen","Zeitüngen","Zeitunge","Zeitungs"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**Autos** : *das Auto → die Autos*. Les mots d’emprunt et les abréviations font leur pluriel en **-s**, sans inflexion."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"Quatre schémas : *das Buch → die Bücher* (-er), *die Lampe → die Lampen* (-n), *der Stuhl → die Stühle* (-e) et *das Auto → die Autos* (-s)."},{"cle":{"type":"trous","trous":[["zeitungen"]]},"affichage":"Zeitungen","explication":"**Anna kauft zwei Zeitungen.** *Zeitung* est féminin : la quasi-totalité des féminins font leur pluriel en **-(e)n**, jamais d’Umlaut."}]$ex$::jsonb),
  ('f04b8338-b125-5b3b-9800-005d4202fbc1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mit den Freunden unterwegs","competence":"manier-langue","situation":"Lea demande à Tim ce qu’il fait samedi. Dans leurs messages, regarde ce qui arrive aux noms quand ils sont au datif pluriel.","documents":[{"id":"sms1","type":"dialogue","modele":"sms","titre":"Am Samstag","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Was machst du am Samstag?"},{"qui":"Tim","texte":"Ich fahre mit meinen Freunden in die Stadt."},{"qui":"Lea","texte":"Fahrt ihr mit den Autos oder mit den Zügen?"},{"qui":"Tim","texte":"Mit den Zügen. Nach dem Kino laufen wir zu Fuß."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux noms qui ont pris un -n au datif pluriel.","aide":"Compare avec le pluriel de base : *die Freunde*, *die Züge*.","type":"zone","document":"sms1","multiple":true},{"enonce":"Touche le seul nom au datif pluriel qui n’a pas pris de -n.","aide":"Regarde comment se termine son pluriel.","type":"zone","document":"sms1","multiple":false},{"enonce":"Complète : « Tim joue avec les enfants. »","aide":"Le pluriel est *Kinder*. Il se termine par -r, pas par -n.","type":"trous","segments":["Tim spielt mit den ",0,"."],"banque":["Kinder","Kinden","Kinders","Kindern"]},{"enonce":"Associe chaque nom au singulier à sa forme au datif pluriel.","aide":"Passe d’abord au pluriel, puis ajoute -n, sauf si le pluriel finit par -s.","type":"association","gauche":[{"id":"g0","texte":"der Zug"},{"id":"g1","texte":"das Haus"},{"id":"g2","texte":"die Stadt"},{"id":"g3","texte":"das Hotel"}],"droite":[{"id":"d0","texte":"den Städten"},{"id":"d1","texte":"den Häusern"},{"id":"d2","texte":"den Zügen"},{"id":"d3","texte":"den Hotels"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m21"]},"explication":"**Freunden** et **Zügen** : au datif pluriel, le nom prend un **-n** s’il n’en a pas déjà un (*die Freunde → mit den Freunden*)."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**Autos** : le pluriel finit déjà par un **-s**, et on n’ajoute pas de -n après un -s (*mit den Autos*)."},{"cle":{"type":"trous","trous":[["kindern"]]},"affichage":"Kindern","explication":"**Tim spielt mit den Kindern.** *die Kinder* se termine par -r, donc le datif pluriel ajoute **-n**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"*die Züge → den Zügen*, *die Häuser → den Häusern*, *die Städte → den Städten* : -n ajouté. *die Hotels → den Hotels* : après -s, rien."}]$ex$::jsonb),
  ('f04b8338-b125-5b3b-9800-005d4202fbc1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un courriel et un tableau à compléter","competence":"manier-langue","situation":"Hannah écrit à Lara après une journée en ville. Son courriel contient deux noms qui ne se comportent pas comme les autres ; un tableau l’aide à trier les pluriels.","documents":[{"id":"mail1","type":"texte","genre":"lettre","titre":"Hallo Lara","blocs":["Heute war ich in der Stadt. Ich habe eine neue Brille gekauft und etwas Obst. Es waren viele Leute da, und die Polizei hat die Straße gesperrt."],"source":"Courriel écrit pour l’exercice"},{"id":"tab1","type":"tableau","titre":"Pluriel et datif pluriel","colonnes":["Singulier","Pluriel","Datif pluriel"],"lignes":[["der Lehrer","die Lehrer","?"],["die Lehrerin","?","?"],["das Auto","die Autos","?"],["das Kind","die Kinder","den Kindern"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le nom qui n’existe qu’au pluriel.","aide":"Il se traduit par « les gens ».","type":"zone","document":"mail1","multiple":false},{"enonce":"Touche le nom singulier que le français traduit par un pluriel (« des lunettes »).","aide":"Il est précédé de *eine*.","type":"zone","document":"mail1","multiple":false},{"enonce":"Complète la ligne *der Lehrer* du tableau : « avec les professeurs ».","aide":"Le pluriel *die Lehrer* ne finit pas par -n.","type":"trous","segments":["mit den ",0],"banque":["Lehrers","Lehrer","Lehreren","Lehrern"]},{"enonce":"Complète la ligne *die Lehrerin* : le pluriel, puis le datif pluriel.","aide":"Les féminins en -in doublent le n au pluriel.","type":"trous","segments":["die ",0," → mit den ",1],"banque":["Lehrerinnen","Lehrerin","Lehrerins","Lehrerinen"]},{"enonce":"Pourquoi écrit-on « mit den Autos » sans -n ?","aide":"Regarde la dernière lettre de *Autos*.","type":"choix","options":[{"id":"a","texte":"Auto est neutre, donc jamais de -n au datif"},{"id":"b","texte":"Un mot emprunté n’a pas de datif pluriel"},{"id":"c","texte":"Le pluriel finit déjà par -s : on n’ajoute rien"},{"id":"d","texte":"Le -n ne s’ajoute qu’après un pluriel en -er"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**Leute** : *die Leute* n’a pas de singulier."},{"cle":{"type":"zone","ids":["m10"]},"explication":"**Brille** : l’allemand dit *eine Brille* (au singulier) là où le français dit « des lunettes »."},{"cle":{"type":"trous","trous":[["lehrern"]]},"affichage":"Lehrern","explication":"**mit den Lehrern** : *die Lehrer* ne se termine ni par -n ni par -s, donc on ajoute **-n** au datif pluriel."},{"cle":{"type":"trous","trous":[["lehrerinnen"],["lehrerinnen"]]},"affichage":"Lehrerinnen · Lehrerinnen","explication":"**die Lehrerinnen → mit den Lehrerinnen**. Les féminins en *-in* doublent le *n* et prennent -en ; le pluriel finit déjà par -n, donc rien ne s’ajoute au datif."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Le pluriel finit déjà par -s.** C’est la seule exception à la règle du -n au datif pluriel : *mit den Autos*."}]$ex$::jsonb),
  ('e2dc63c4-553b-5b46-a015-12ae322b4366'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une carte postale de Vienne","competence":"manier-langue","situation":"Mia est en voyage à Vienne et écrit à sa grand-mère. Elle décrit la ville, les gens et le temps.","documents":[{"id":"wien","type":"texte","genre":"lettre","titre":"Liebe Oma","blocs":["Wir sind jetzt in Wien. Die Stadt ist groß und die Leute sind freundlich. Das Wetter bleibt schön. Mein Bruder hat ein neues Fahrrad."],"source":"Carte postale écrite pour l’exercice"}],"questions":[{"enonce":"Touche les trois adjectifs attributs, ceux qui suivent « ist », « sind » ou « bleibt ».","aide":"Ils viennent après le verbe, pas devant un nom.","type":"zone","document":"wien","multiple":true},{"enonce":"Complète : « Les enfants sont fatigués. »","aide":"Après *sein*, l’adjectif ne change pas.","type":"trous","segments":["Die Kinder sind ",0,"."],"banque":["müden","müde","müder","müdes"]},{"enonce":"Pourquoi écrit-on « Die Stadt ist groß » et non « große » ?","aide":"Pense à la place de l’adjectif par rapport au verbe.","type":"choix","options":[{"id":"a","texte":"Après sein, l’adjectif attribut reste invariable"},{"id":"b","texte":"Après ist, l’adjectif prend toujours -en"},{"id":"c","texte":"Stadt est féminin, il faut donc un -e"},{"id":"d","texte":"Groß est un attribut, donc il se décline"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m13","m17"]},"explication":"**groß**, **freundlich** et **schön** sont attributs : ils suivent *sein* ou *bleiben*. *neues* est épithète, devant *Fahrrad*."},{"cle":{"type":"trous","trous":[["mude"]]},"affichage":"müde","explication":"**Die Kinder sind müde.** L’adjectif attribut reste à sa forme nue, même avec un sujet au pluriel."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Après *sein*, *werden* et *bleiben*, l’adjectif attribut ne se décline jamais.** Le français accorde (« grande »), l’allemand non."}]$ex$::jsonb),
  ('e2dc63c4-553b-5b46-a015-12ae322b4366'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une annonce : devant ou après ?","competence":"analyser-texte","situation":"Jonas a mis une annonce sur le tableau du lycée pour vendre des meubles. Observe où se trouvent les adjectifs.","documents":[{"id":"anz","type":"texte","genre":"article","titre":"Zu verkaufen","blocs":["Ein alter Tisch und ein neues Fahrrad. Der Tisch ist stabil, das Fahrrad ist schnell und die Stühle sind sehr bequem."],"source":"Petite annonce écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux adjectifs épithètes, ceux qui sont devant le nom.","aide":"Ils portent une terminaison, et un nom les suit tout de suite.","type":"zone","document":"anz","multiple":true},{"enonce":"Touche les trois adjectifs attributs, qui ne portent aucune terminaison.","aide":"Ils viennent après *ist* ou *sind*.","type":"zone","document":"anz","multiple":true},{"enonce":"Range chaque phrase : l’adjectif est-il attribut ou épithète ?","aide":"Cherche si l’adjectif vient après le verbe ou devant le nom.","type":"categories","categories":[{"id":"c0","texte":"Attribut (invariable)"},{"id":"c1","texte":"Épithète (décliné)"}],"items":[{"id":"i0","texte":"Das Auto ist teuer."},{"id":"i1","texte":"Die Kinder sind müde."},{"id":"i2","texte":"Die müden Kinder schlafen."},{"id":"i3","texte":"Ein teures Auto steht da."}]},{"enonce":"Remets en ordre : « Le chat est très petit. » La phrase commence par Die Katze.","aide":"Le verbe est en deuxième position ; l’attribut vient en dernier.","type":"ordre","items":[{"id":"a","texte":"sehr"},{"id":"b","texte":"ist"},{"id":"c","texte":"Die Katze"},{"id":"d","texte":"klein"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m5"]},"explication":"**alter** (*ein alter Tisch*) et **neues** (*ein neues Fahrrad*) sont devant le nom : ils se déclinent."},{"cle":{"type":"zone","ids":["m10","m14","m20"]},"explication":"**stabil**, **schnell** et **bequem** suivent le verbe *sein* : ils restent invariables, même pour *die Stühle* au pluriel."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Après le verbe (*ist teuer*, *sind müde*), l’adjectif ne change pas. Devant le nom (*ein teures Auto*, *die müden Kinder*), il se décline."},{"cle":{"type":"ordre","ids":["c","b","a","d"]},"explication":"**Die Katze ist sehr klein.** L’adjectif attribut, sans terminaison, se place après le verbe."}]$ex$::jsonb),
  ('e2dc63c4-553b-5b46-a015-12ae322b4366'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Messages dans le train : attribut, adverbe, comparatif","competence":"manier-langue","situation":"Emma discute avec Paul, qui revient d’un voyage à Hambourg. Les mêmes mots changent de rôle : adjectif, adverbe ou comparatif.","documents":[{"id":"train","type":"dialogue","modele":"sms","titre":"Nach Hamburg","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Wie war die Fahrt nach Hamburg?"},{"qui":"Paul","texte":"Der Zug fährt schnell, aber er ist teuer."},{"qui":"Emma","texte":"Und dein Bruder? Er singt jetzt im Chor."},{"qui":"Paul","texte":"Ja, er singt schön. Aber der Bus ist billiger."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux adverbes : ils décrivent un verbe, et non un nom.","aide":"En allemand, l’adverbe a la même forme que l’adjectif.","type":"zone","document":"train","multiple":true},{"enonce":"Touche l’adjectif attribut qui suit « ist » et garde sa forme nue.","aide":"Ne choisis pas le mot qui se termine par -er.","type":"zone","document":"train","multiple":false},{"enonce":"Dans « Der Bus ist billiger », que marque la terminaison -er ?","aide":"Emma et Paul comparent le train et le bus.","type":"choix","options":[{"id":"a","texte":"Le comparatif"},{"id":"b","texte":"Le masculin singulier"},{"id":"c","texte":"Le génitif"},{"id":"d","texte":"Le pluriel"}],"multiple":false},{"enonce":"Associe chaque phrase allemande à sa traduction.","aide":"*schön* est « bien » après un verbe d’action, « beau » après *sein* ou *bleiben*.","type":"association","gauche":[{"id":"g0","texte":"Er singt schön"},{"id":"g1","texte":"Das Lied ist schön"},{"id":"g2","texte":"Der Bus ist billiger"},{"id":"g3","texte":"Das Wetter bleibt schön"}],"droite":[{"id":"d0","texte":"Le temps reste beau"},{"id":"d1","texte":"Le bus est moins cher"},{"id":"d2","texte":"La chanson est belle"},{"id":"d3","texte":"Il chante bien"}]},{"enonce":"Remets en ordre : « Je trouve le film ennuyeux. » La phrase commence par Ich.","aide":"*finden* est en deuxième position ; l’attribut du COD vient à la fin.","type":"ordre","items":[{"id":"a","texte":"finde"},{"id":"b","texte":"Ich"},{"id":"c","texte":"langweilig"},{"id":"d","texte":"den Film"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m25"]},"explication":"**schnell** (*fährt schnell*) et **schön** (*singt schön*) complètent un verbe : ce sont des adverbes, sans terminaison."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**teuer** suit *ist* : c’est un attribut invariable. *billiger* est un comparatif : son -er est la marque du comparatif, pas un accord."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Le comparatif** : *billiger* = « moins cher ». Ce n’est pas un accord avec *Bus*."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"Le même mot *schön* sert d’adverbe (*singt schön* = « chante bien ») ou d’attribut (*ist schön* = « est belle »)."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**Ich finde den Film langweilig.** Avec *finden*, l’adjectif qualifie le COD et reste invariable."}]$ex$::jsonb),
  ('62ec0fde-c670-5dbe-a47c-453fdbb92daf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le menu du Café zur Sonne","competence":"comprendre-langue","situation":"Jan lit l’ardoise du café en bas de chez lui. Chaque ligne a un adjectif devant un nom, avec ou sans déterminant.","documents":[{"id":"menu","type":"fiche","modele":"menu","entete":"Café zur Sonne","sousTitre":"Heute im Angebot","emoji":"☕","lignes":[{"texte":"Kalte Milch","valeur":"1,20 €","id":"z1"},{"texte":"Frisches Brot","valeur":"2,00 €","id":"z2"},{"texte":"Die heiße Suppe","valeur":"3,50 €","id":"z3"},{"texte":"Ein warmer Apfelkuchen","valeur":"2,80 €","id":"z4"}],"pied":"Menu écrit pour l’exercice","teinte":"ambre"}],"questions":[{"enonce":"Touche les deux lignes où l’adjectif est employé sans déterminant (déclinaison forte).","aide":"Cherche les lignes qui commencent directement par l’adjectif.","type":"zone","document":"menu","multiple":true},{"enonce":"Pourquoi « Die heiße Suppe » se termine-t-il en -e ?","aide":"Quel mot précède l’adjectif ?","type":"choix","options":[{"id":"a","texte":"Parce qu’il n’y a aucun déterminant"},{"id":"b","texte":"Parce que heiß est un adjectif invariable"},{"id":"c","texte":"Parce que « die » porte déjà la marque du cas"},{"id":"d","texte":"Parce que Suppe est un nom masculin"}],"multiple":false},{"enonce":"Complète : « Au petit-déjeuner, je mange du bon pain. »","aide":"Il n’y a pas de déterminant, et *Brot* est neutre.","type":"trous","segments":["Zum Frühstück esse ich ",0," Brot."],"banque":["gutes","gute","guter","guten"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**Kalte Milch** et **Frisches Brot** : sans article, l’adjectif porte lui-même la marque du cas (*-e* pour le féminin, *-es* pour le neutre)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Quand le déterminant (*die*) porte déjà la marque du cas, l’adjectif prend une terminaison faible : **-e** ici."},{"cle":{"type":"trous","trous":[["gutes"]]},"affichage":"gutes","explication":"**gutes** : sans déterminant, l’adjectif reprend la terminaison de l’article défini ; pour un neutre à l’accusatif, c’est **-es**."}]$ex$::jsonb),
  ('62ec0fde-c670-5dbe-a47c-453fdbb92daf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les petites annonces de Lukas","competence":"manier-langue","situation":"Lukas vide sa chambre et publie une annonce. Il doit choisir la bonne terminaison pour chaque adjectif.","documents":[{"id":"kleinanz","type":"texte","genre":"article","titre":"Zu verkaufen","blocs":["Verkaufe meinen alten Computer, einen schnellen Drucker und gute Bücher. Dazu gibt es frische Eier vom Bauernhof."],"source":"Annonce écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux adjectifs employés sans déterminant (déclinaison forte).","aide":"Cherche les adjectifs qui précèdent directement un nom au pluriel.","type":"zone","document":"kleinanz","multiple":true},{"enonce":"Touche l’adjectif qui suit un possessif (« meinen »).","aide":"C’est un masculin à l’accusatif.","type":"zone","document":"kleinanz","multiple":false},{"enonce":"Range chaque groupe nominal selon sa déclinaison.","aide":"Regarde ce qui précède l’adjectif : article défini, article indéfini ou rien.","type":"categories","categories":[{"id":"c0","texte":"Faible (après der, die, das)"},{"id":"c1","texte":"Mixte (après ein, mein)"},{"id":"c2","texte":"Forte (sans déterminant)"}],"items":[{"id":"i0","texte":"der alte Mann"},{"id":"i1","texte":"ein alter Mann"},{"id":"i2","texte":"gute Freunde"},{"id":"i3","texte":"mein neues Auto"},{"id":"i4","texte":"die neue Schule"},{"id":"i5","texte":"alter Wein"}]},{"enonce":"Complète avec la bonne forme : « C’est une haute montagne et une voiture chère. »","aide":"*hoch* perd son c ; *teuer* perd son e devant une terminaison.","type":"trous","segments":["Das ist ein ",0," Berg und ein ",1," Auto."],"banque":["teures","teueres","hohes","hocher","hoher"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m13"]},"explication":"**gute** (*gute Bücher*) et **frische** (*frische Eier*) : pas de déterminant, donc l’adjectif porte la marque du cas (*-e* au pluriel)."},{"cle":{"type":"zone","ids":["m2"]},"explication":"**alten** : après le possessif *meinen*, qui marque déjà le cas, l’adjectif prend **-en**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c1","i4":"c0","i5":"c2"}},"explication":"Après *der/die/das* : faible. Après *ein/mein* : mixte. Sans déterminant : forte (*alter Wein*, *gute Freunde*)."},{"cle":{"type":"trous","trous":[["hoher"],["teures"]]},"affichage":"hoher · teures","explication":"**ein hoher Berg** (*hoch* → *hoh-*, + *-er*) et **ein teures Auto** (*teuer* → *teur-*, + *-es*) : *ein* ne marque ni le masculin ni le neutre, l’adjectif le fait."}]$ex$::jsonb),
  ('62ec0fde-c670-5dbe-a47c-453fdbb92daf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ma nouvelle chambre : lettre et grille","competence":"manier-langue","situation":"Mia emménage dans un nouveau logement. Elle décrit sa chambre à une amie, puis révise la déclinaison faible avec un tableau.","documents":[{"id":"zimmer","type":"texte","genre":"lettre","titre":"Hallo Mia","blocs":["Mein neues Zimmer ist toll! Ein großes Bett steht am Fenster. Neben dem alten Schrank hängt ein rosa Poster. Auf dem Tisch liegt ein dunkles Heft."],"source":"Lettre écrite pour l’exercice"},{"id":"tabdekl","type":"tableau","titre":"La déclinaison faible","colonnes":["Cas","Masculin","Féminin","Neutre","Pluriel"],"lignes":[["Nominatif","der alte Mann","die alte Frau","das alte Haus","die alten Kinder"],["Accusatif","den alten Mann","?","?","die alten Kinder"],["Datif","dem alten Mann","der alten Frau","?","?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’adjectif qui ne prend jamais de terminaison.","aide":"C’est une couleur empruntée.","type":"zone","document":"zimmer","multiple":false},{"enonce":"Touche l’adjectif qui a perdu un e pour recevoir sa terminaison.","aide":"Compare avec *dunkel*.","type":"zone","document":"zimmer","multiple":false},{"enonce":"Pourquoi « ein großes Bett », mais « eine große Lampe » ?","aide":"Compare la terminaison de *ein* et celle de *eine*.","type":"choix","options":[{"id":"a","texte":"Ein ne marque pas le neutre, l’adjectif le fait"},{"id":"b","texte":"Après ein, l’adjectif prend toujours la forme -en"},{"id":"c","texte":"Bett est féminin, l’adjectif prend donc un -e"},{"id":"d","texte":"Groß est un attribut, donc il se décline ici"}],"multiple":false},{"enonce":"Complète les cases du tableau : accusatif féminin et accusatif neutre.","aide":"À l’accusatif, féminin et neutre ressemblent au nominatif.","type":"trous","segments":["die ",0," Frau · das ",1," Haus"],"banque":["alten","alte","alter","altes"]},{"enonce":"Complète les cases du datif : le neutre, puis le pluriel.","aide":"Au datif, l’adjectif faible prend la même terminaison partout.","type":"trous","segments":["dem ",0," Haus · den ",1," Kindern"],"banque":["alte","altes","alten","alter"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"**rosa** est invariable, comme *lila* : *ein rosa Poster*."},{"cle":{"type":"zone","ids":["m24"]},"explication":"**dunkles** : *dunkel* perd son *e* devant une terminaison (*ein dunkles Heft*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"*ein* est sans marque au neutre : l’adjectif porte **-es**. *eine* marque déjà le féminin : l’adjectif se contente de **-e**."},{"cle":{"type":"trous","trous":[["alte"],["alte"]]},"affichage":"alte · alte","explication":"**die alte Frau**, **das alte Haus** : à l’accusatif, le féminin et le neutre gardent le **-e** du nominatif."},{"cle":{"type":"trous","trous":[["alten"],["alten"]]},"affichage":"alten · alten","explication":"**dem alten Haus**, **den alten Kindern** : au datif (et au génitif), la terminaison faible est toujours **-en**."}]$ex$::jsonb),
  ('309ddd5f-f462-5553-86b3-4dd17ce4a56f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La famille de Lena","competence":"comprendre-langue","situation":"Lena présente sa famille à sa nouvelle classe. Observe les petits mots qui disent « mon », « ma » ou « notre ».","documents":[{"id":"fam","type":"texte","genre":"recit","titre":"Meine Familie","blocs":["Das ist meine Familie. Mein Vater heißt Karl, meine Mutter heißt Eva. Unser Hund heißt Rex."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le possessif qui veut dire « notre ».","aide":"Il ne commence pas par m-.","type":"zone","document":"fam","multiple":false},{"enonce":"Associe chaque possessif à son sens.","aide":"*euer* s’adresse à plusieurs personnes que l’on tutoie.","type":"association","gauche":[{"id":"g0","texte":"mein"},{"id":"g1","texte":"dein"},{"id":"g2","texte":"unser"},{"id":"g3","texte":"euer"}],"droite":[{"id":"d0","texte":"votre"},{"id":"d1","texte":"notre"},{"id":"d2","texte":"ton"},{"id":"d3","texte":"mon"}]},{"enonce":"Complète : « Voici mon frère et voici ma sœur. »","aide":"Le possessif se décline comme *ein* : un -e pour le féminin.","type":"trous","segments":["Das ist ",0," Bruder und das ist ",1," Schwester."],"banque":["mein","meine","meinen","meiner"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"**Unser** : *unser Hund* = « notre chien »."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"*mein* = mon, *dein* = ton, *unser* = notre, *euer* = votre (à plusieurs amis)."},{"cle":{"type":"trous","trous":[["mein"],["meine"]]},"affichage":"mein · meine","explication":"**mein Bruder** (masculin, sans terminaison) et **meine Schwester** (féminin, -e)."}]$ex$::jsonb),
  ('309ddd5f-f462-5553-86b3-4dd17ce4a56f'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La fête de l’école","competence":"manier-langue","situation":"C’est la fête de l’école. Un article de présentation dit avec qui chacun arrive : à chaque fois, il faut regarder QUI possède et CE QUI est possédé.","documents":[{"id":"fest","type":"texte","genre":"article","titre":"Schulfest","blocs":["Heute ist Schulfest. Anna kommt mit ihrem Bruder. Peter kommt mit seiner Schwester. Die Kinder spielen mit ihren Freunden."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le possessif qui renvoie à un garçon, Peter.","aide":"Son radical commence par *s-*.","type":"zone","document":"fest","multiple":false},{"enonce":"Touche le possessif qui renvoie à Anna.","aide":"Son radical est *ihr-*.","type":"zone","document":"fest","multiple":false},{"enonce":"Pourquoi « seiner » finit-il par -er ?","aide":"La terminaison dépend de l’objet possédé, pas du possesseur.","type":"choix","options":[{"id":"a","texte":"Schwester est féminin, et le nom est au datif"},{"id":"b","texte":"Le possesseur est neutre, donc on met -er"},{"id":"c","texte":"Mit demande le génitif, d’où la terminaison -er"},{"id":"d","texte":"Peter est un homme, donc la terminaison est -er"}],"multiple":false},{"enonce":"Complète : « Avez-vous vu vos parents ? » (on tutoie plusieurs amis)","aide":"*euer* perd son e devant une terminaison.","type":"trous","segments":["Habt ihr ",0," Eltern gesehen?"],"banque":["eurer","euere","euer","eure"]},{"enonce":"Remets en ordre : « Il met son manteau. » La phrase commence par Er.","aide":"Avec un vêtement, l’allemand emploie l’article et non le possessif.","type":"ordre","items":[{"id":"a","texte":"zieht"},{"id":"b","texte":"an"},{"id":"c","texte":"den Mantel"},{"id":"d","texte":"Er"},{"id":"e","texte":"sich"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**seiner** : le radical *sein-* vient du possesseur (Peter, un homme)."},{"cle":{"type":"zone","ids":["m6"]},"explication":"**ihrem** : le radical *ihr-* vient du possesseur (Anna, une femme) ; *-em* vient de *der Bruder* au datif."},{"cle":{"type":"choix","ids":["a"]},"explication":"La terminaison suit l’**objet possédé** : *Schwester* est féminin et au datif après *mit* ; le radical *sein-* suit le possesseur."},{"cle":{"type":"trous","trous":[["eure"]]},"affichage":"eure","explication":"**Habt ihr eure Eltern gesehen?** *euer* devient *eur-* devant une terminaison, et le pluriel prend **-e**."},{"cle":{"type":"ordre","ids":["d","a","e","c","b"]},"explication":"**Er zieht sich den Mantel an.** Pas de possessif : *den Mantel* + *sich* (datif) disent « son manteau »."}]$ex$::jsonb),
  ('309ddd5f-f462-5553-86b3-4dd17ce4a56f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Au bureau des objets trouvés","competence":"raisonner","situation":"Au bureau des objets trouvés, Herr Braun vérifie à qui appartiennent plusieurs affaires. Un tableau rappelle qui est le propriétaire de chaque objet.","documents":[{"id":"fund","type":"dialogue","modele":"sms","titre":"Im Fundbüro","participants":[{"nom":"Herr Braun","emoji":"👨","cote":"gauche"},{"nom":"Frau Weiß","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Herr Braun","texte":"Guten Tag, Frau Weiß. Ist das Ihre Jacke?"},{"qui":"Frau Weiß","texte":"Nein, meine Jacke ist grün. Aber das ist die Mütze von meinem Sohn."},{"qui":"Herr Braun","texte":"Und der Schirm? Gehört er Ihrem Mann?"},{"qui":"Frau Weiß","texte":"Ja, das ist seiner. Und die Handschuhe sind unsere."}],"source":"Dialogue écrit pour l’exercice"},{"id":"liste","type":"tableau","titre":"Liste des objets","colonnes":["Objet","Genre","Propriétaire"],"lignes":[["die Tasche","féminin","Frau Weiß"],["das Handy","neutre","Lena, sa fille"],["die Schlüssel","pluriel","Ben, son fils"]],"source":"Liste écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux possessifs de politesse (« votre »).","aide":"Ils s’écrivent avec une majuscule, au milieu de la phrase.","type":"zone","document":"fund","multiple":true},{"enonce":"Touche les deux possessifs employés seuls, sans nom derrière.","aide":"Ils répondent à « À qui est-ce ? ».","type":"zone","document":"fund","multiple":true},{"enonce":"Herr Braun parle des propriétaires à un collègue. Complète d’après la liste.","aide":"Radical d’après le possesseur (femme ou homme), terminaison d’après l’objet (genre).","type":"trous","segments":["Das ist ",0," Tasche. Das ist ",1," Handy. Das sind ",2," Schlüssel."],"banque":["seine","ihrem","ihr","sein","ihre"]},{"enonce":"Pourquoi « Ihre Jacke » prend-il une majuscule dans le dialogue ?","aide":"Regarde à qui Herr Braun s’adresse.","type":"choix","options":[{"id":"a","texte":"Herr Braun vouvoie Frau Weiß : c’est la politesse"},{"id":"b","texte":"Ihre veut dire « leur » et prend toujours une majuscule"},{"id":"c","texte":"Ihre est placé juste après un point"},{"id":"d","texte":"Ihre est un nom propre dans cette phrase"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m26"]},"explication":"**Ihre** et **Ihrem** : Herr Braun vouvoie Frau Weiß, donc *Ihr-* prend une majuscule."},{"cle":{"type":"zone","ids":["m31","m36"]},"explication":"**seiner** et **unsere** : employé seul, le possessif prend les terminaisons de l’article défini (*das ist seiner*)."},{"cle":{"type":"trous","trous":[["ihre"],["ihr"],["seine"]]},"affichage":"ihre · ihr · seine","explication":"**ihre Tasche** (Frau Weiß, *Tasche* féminin), **ihr Handy** (Lena, *Handy* neutre : pas de terminaison), **seine Schlüssel** (Ben, pluriel)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Quand on **vouvoie**, le possessif s’écrit avec une majuscule : *Ihre Jacke* = « votre veste ». Sans majuscule, *ihre* voudrait dire « sa » (à elle) ou « leur »."}]$ex$::jsonb),
  ('56ad254e-04ec-5598-b077-c62d23ba04f6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Sur le parking de l’école","competence":"comprendre-langue","situation":"Le journal de l’école décrit les véhicules garés devant le lycée. Les propriétaires sont indiqués de deux manières différentes.","documents":[{"id":"park","type":"texte","genre":"article","titre":"Auf dem Parkplatz","blocs":["Auf dem Parkplatz stehen drei Fahrzeuge. Peters Auto ist blau, Annas Roller ist rot. Das Auto des Lehrers ist schwarz."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux génitifs saxons : le nom du possesseur est devant, avec un -s.","aide":"Ce sont des prénoms, sans article.","type":"zone","document":"park","multiple":true},{"enonce":"Touche l’article qui introduit un génitif ordinaire, placé derrière le nom.","aide":"Cet article est suivi d’un nom masculin avec -s.","type":"zone","document":"park","multiple":false},{"enonce":"Complète : « la maison du père et la chambre de la mère ».","aide":"Masculin et neutre : *des* ; féminin et pluriel : *der*.","type":"trous","segments":["Das Haus ",0," Vaters und das Zimmer ",1," Mutter."],"banque":["dem","den","des","der"]}]}$ex$::jsonb,
