  ('56ad254e-04ec-5598-b077-c62d23ba04f6'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"À qui est ce vélo ?","competence":"manier-langue","situation":"Lena veut savoir à qui appartiennent un téléphone et un vélo. Tom répond de trois manières différentes.","documents":[{"id":"wem","type":"dialogue","modele":"sms","titre":"Wessen Handy?","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Wessen Handy liegt da?"},{"qui":"Tom","texte":"Das ist das Handy von meinem Bruder."},{"qui":"Lena","texte":"Und das Fahrrad vor der Tür?"},{"qui":"Tom","texte":"Das ist Annas Fahrrad. Es bleibt wegen des Regens hier."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition de la tournure orale « de + datif » : le possesseur est derrière.","aide":"Elle introduit « mon frère ».","type":"zone","document":"wem","multiple":false},{"enonce":"Touche le génitif saxon : le possesseur est devant le nom, sans article.","aide":"C’est un prénom terminé par -s.","type":"zone","document":"wem","multiple":false},{"enonce":"Touche la préposition qui régit le génitif et veut dire « à cause de ».","aide":"Elle est suivie de *des Regens*.","type":"zone","document":"wem","multiple":false},{"enonce":"Range chaque tournure selon sa construction.","aide":"Regarde où se trouve le possesseur et s’il y a un *von*.","type":"categories","categories":[{"id":"c0","texte":"Génitif saxon"},{"id":"c1","texte":"Génitif ordinaire"},{"id":"c2","texte":"von + datif"}],"items":[{"id":"i0","texte":"Lenas Tasche"},{"id":"i1","texte":"das Auto von meinem Vater"},{"id":"i2","texte":"die Tasche von meiner Mutter"},{"id":"i3","texte":"das Auto des Vaters"},{"id":"i4","texte":"die Tasche der Frau"},{"id":"i5","texte":"Peters Auto"}]},{"enonce":"Complète : « Pendant l’été, nous allons à la mer. »","aide":"Le sens est « pendant » : une durée.","type":"trous","segments":[0," des Sommers fahren wir ans Meer."],"banque":["Trotz","Statt","Während","Wegen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**von** : *das Handy von meinem Bruder* est la tournure orale, avec un datif."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**Annas** : *Annas Fahrrad*, sans article et sans apostrophe."},{"cle":{"type":"zone","ids":["m23"]},"explication":"**wegen** : *wegen des Regens*. Les prépositions *wegen*, *trotz*, *während*, *statt* régissent le génitif."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c2","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Le **génitif saxon** met le possesseur devant (*Lenas Tasche*), le **génitif ordinaire** derrière avec *des* ou *der*, et *von* + datif est la forme orale."},{"cle":{"type":"trous","trous":[["wahrend"]]},"affichage":"Während","explication":"**Während des Sommers** : *während* + génitif veut dire « pendant »."}]$ex$::jsonb),
  ('56ad254e-04ec-5598-b077-c62d23ba04f6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le journal du quartier","competence":"analyser-texte","situation":"Le journal du quartier raconte les travaux de l’été. Son vocabulaire est celui de l’écrit soigné : il utilise des prépositions suivies du génitif.","documents":[{"id":"viertel","type":"texte","genre":"article","titre":"Bei uns im Viertel","blocs":["Während des Sommers war die Straße gesperrt. Trotz der Hitze arbeiteten die Männer jeden Tag. Statt des alten Marktes gibt es jetzt einen Parkplatz.","Der Bürgermeister war nicht da, wegen seiner Krankheit."],"source":"Article écrit pour l’exercice"},{"id":"tabgen","type":"tableau","titre":"L’article et le nom au génitif","colonnes":["Genre","Article","Le nom"],"lignes":[["Masculin","des","prend -(e)s"],["Neutre","des","?"],["Féminin","der","?"],["Pluriel","der","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre prépositions qui régissent le génitif.","aide":"Le sens est : pendant, malgré, au lieu de, à cause de.","type":"zone","document":"viertel","multiple":true},{"enonce":"Touche les deux noms féminins au génitif.","aide":"Leur article est *der*, ou le possessif *seiner*.","type":"zone","document":"viertel","multiple":true},{"enonce":"Complète d’après le tableau : « pendant l’année » (*das Jahr*).","aide":"Le nom neutre prend -(e)s au génitif, comme le masculin.","type":"trous","segments":["während des ",0],"banque":["Jahres","Jahren","Jahre","Jahr"]},{"enonce":"Associe chaque préposition à son sens.","aide":"Cherche la phrase du journal où chaque mot est utilisé.","type":"association","gauche":[{"id":"g0","texte":"wegen"},{"id":"g1","texte":"trotz"},{"id":"g2","texte":"während"},{"id":"g3","texte":"statt"}],"droite":[{"id":"d0","texte":"pendant"},{"id":"d1","texte":"à cause de"},{"id":"d2","texte":"malgré"},{"id":"d3","texte":"au lieu de"}]},{"enonce":"Remets en ordre : « À cause de la pluie, je reste à la maison. » La phrase commence par Wegen des Regens.","aide":"Le groupe prépositionnel est en première position : le verbe passe devant le sujet.","type":"ordre","items":[{"id":"a","texte":"Wegen des Regens"},{"id":"b","texte":"ich"},{"id":"c","texte":"zu Hause"},{"id":"d","texte":"bleibe"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m7","m15","m29"]},"explication":"**Während**, **Trotz**, **Statt** et **wegen** régissent le génitif."},{"cle":{"type":"zone","ids":["m9","m31"]},"explication":"**Hitze** et **Krankheit** sont féminins : au génitif, le nom ne prend aucune marque (*der Hitze*, *seiner Krankheit*)."},{"cle":{"type":"trous","trous":[["jahres"]]},"affichage":"Jahres","explication":"**während des Jahres** : au génitif, le nom masculin ou neutre prend **-(e)s** ; le féminin et le pluriel ne changent pas."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"*wegen* = à cause de, *trotz* = malgré, *während* = pendant, *statt* = au lieu de."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"**Wegen des Regens bleibe ich zu Hause.** Le groupe en tête occupe la première place ; le verbe reste en deuxième, avant *ich*."}]$ex$::jsonb),
  ('767d36b0-23c9-5d5a-a234-49c83e6b76a9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui est le plus grand ?","competence":"lire-tableau","situation":"Trois élèves de l’équipe de volley ont été mesurés par le professeur de sport. Il note leur âge et leur taille.","documents":[{"id":"equipe","type":"tableau","titre":"L’équipe de volley","colonnes":["Name","Alter","Größe (cm)"],"lignes":[["Lena",13,158],["Tim",15,172],["Mia",15,165]],"enteteLignes":true,"source":"Données inventées pour l’exercice"}],"questions":[{"enonce":"D’après le tableau, quelle phrase est juste ?","aide":"Compare les tailles de Tim et de Lena, et regarde le mot qui suit *größer*.","type":"choix","options":[{"id":"a","texte":"Tim ist größer wie Lena"},{"id":"b","texte":"Mia ist so groß wie Tim"},{"id":"c","texte":"Tim ist größer als Lena"},{"id":"d","texte":"Lena ist größer als Tim"}],"multiple":false},{"enonce":"Complète : « Lena est plus jeune que Tim. »","aide":"Une inégalité s’exprime avec comparatif + ...","type":"trous","segments":["Lena ist jünger ",0," Tim."],"banque":["als","mehr","wie","so"]},{"enonce":"Complète d’après les âges : « Mia est plus âgée que Lena. »","aide":"*alt* prend un Umlaut au comparatif.","type":"trous","segments":["Mia ist ",0," als Lena."],"banque":["älteres","mehr alt","älter","alter"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"**Tim ist größer als Lena** : Tim mesure 172 cm, Lena 158 cm. Après un comparatif, on emploie *als*, jamais *wie*."},{"cle":{"type":"trous","trous":[["als"]]},"affichage":"als","explication":"**Lena ist jünger als Tim.** Supériorité ou infériorité : comparatif + **als**."},{"cle":{"type":"trous","trous":[["alter"]]},"affichage":"älter","explication":"**Mia ist älter als Lena** : Mia a 15 ans, Lena 13 ; *alt → älter*, avec Umlaut."}]$ex$::jsonb),
  ('767d36b0-23c9-5d5a-a234-49c83e6b76a9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux smartphones à comparer","competence":"lire-tableau","situation":"Yasmin hésite entre deux smartphones. Elle compare leur prix, leur poids et la durée de leur batterie.","documents":[{"id":"phones","type":"tableau","titre":"Zwei Smartphones","colonnes":["","Modell A","Modell B"],"lignes":[["Preis (€)",300,450],["Gewicht (g)",160,140],["Akku (h)",20,30]],"enteteLignes":true,"source":"Données inventées pour l’exercice"}],"questions":[{"enonce":"De combien d’euros le modèle B est-il plus cher que le modèle A ?","aide":"Soustrais les deux prix.","type":"nombre","unite":"€"},{"enonce":"Complète : « Le modèle A est moins cher que le modèle B. »","aide":"Adjectif + -er, sans mot supplémentaire.","type":"trous","segments":["Modell A ist ",0," als Modell B."],"banque":["billigere","mehr billig","billig","billiger"]},{"enonce":"Quelle phrase est FAUSSE d’après le tableau ?","aide":"Cherche la phrase qui contredit un prix, un poids ou une durée du tableau.","type":"choix","options":[{"id":"a","texte":"Modell A ist nicht so leicht wie Modell B"},{"id":"b","texte":"Modell B ist so teuer wie Modell A"},{"id":"c","texte":"Modell B ist leichter als Modell A"},{"id":"d","texte":"Modell A ist billiger als Modell B"}],"multiple":false},{"enonce":"Remets en ordre : « Le modèle B est plus cher que le modèle A. » La phrase commence par Modell B.","aide":"Comparatif, puis *als* et le second terme.","type":"ordre","items":[{"id":"a","texte":"Modell A"},{"id":"b","texte":"Modell B"},{"id":"c","texte":"teurer"},{"id":"d","texte":"als"},{"id":"e","texte":"ist"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":150,"tolerance":0},"affichage":"150 €","explication":"**150 €** : 450 − 300 = 150. On écrit *Modell B ist teurer als Modell A*."},{"cle":{"type":"trous","trous":[["billiger"]]},"affichage":"billiger","explication":"**Modell A ist billiger als Modell B.** Le comparatif se forme avec **-er** : on n’emploie jamais *mehr* devant un adjectif."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Modell B ist so teuer wie Modell A** est fausse : B coûte 450 €, A 300 €. Les trois autres correspondent au tableau."},{"cle":{"type":"ordre","ids":["b","e","c","d","a"]},"explication":"**Modell B ist teurer als Modell A.** Structure : sujet + *ist* + comparatif + **als** + second terme."}]$ex$::jsonb),
  ('767d36b0-23c9-5d5a-a234-49c83e6b76a9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Mon allemand s’améliore","competence":"argumenter","situation":"Clara tient un petit carnet de ses révisions d’allemand. Elle a tracé son temps de travail par semaine et raconte ses progrès dans une lettre.","documents":[{"id":"lernzeit","type":"graphique","forme":"barres","titre":"Meine Lernzeit pro Tag","categories":["Woche 1","Woche 2","Woche 3","Woche 4"],"series":[{"nom":"Minuten","valeurs":[15,25,40,55],"teinte":"turquoise"}],"axeY":{"titre":"Lernzeit","unite":"Minuten","min":0,"max":60,"pas":10},"axeX":{"titre":"Woche"},"valeurs":false,"source":"Données inventées pour l’exercice"},{"id":"brief","type":"texte","genre":"lettre","titre":"Hallo Lena","blocs":["Ich lerne jede Woche länger Deutsch. Mein älterer Bruder Paul lernt mehr als ich, aber ich verstehe schon viel."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche la semaine pendant laquelle Clara a travaillé le plus longtemps.","aide":"Cherche la barre la plus haute.","type":"zone","document":"lernzeit","multiple":false},{"enonce":"Combien de minutes de plus par jour Clara travaille-t-elle en semaine 4 qu’en semaine 1 ?","aide":"Lis les deux barres, puis soustrais.","type":"nombre","unite":"minutes"},{"enonce":"Touche le comparatif qui porte, en plus, une terminaison de déclinaison.","aide":"Il est devant un nom et se termine par -er.","type":"zone","document":"brief","multiple":false},{"enonce":"Quelle phrase compare correctement les semaines 4 et 2 ?","aide":"Après un comparatif, on emploie *als*, et *mehr* ne se place jamais devant un adjectif.","type":"choix","options":[{"id":"a","texte":"In Woche 4 lerne ich länger wie in Woche 2"},{"id":"b","texte":"In Woche 4 lerne ich länger als in Woche 2"},{"id":"c","texte":"In Woche 4 lerne ich mehr lang als in Woche 2"},{"id":"d","texte":"In Woche 4 lerne ich so länger als in Woche 2"}],"multiple":false},{"enonce":"Remets en ordre : « Plus Paul s’exerce en allemand, mieux il parle. » La phrase commence par Je mehr Deutsch.","aide":"Après *je…*, le verbe est à la fin de la proposition ; après *desto…*, le verbe est en deuxième position.","type":"ordre","items":[{"id":"a","texte":"desto besser"},{"id":"b","texte":"Paul"},{"id":"c","texte":"Je mehr Deutsch"},{"id":"d","texte":"spricht er"},{"id":"e","texte":"übt,"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"**Woche 4** : environ 55 minutes par jour, c’est la barre la plus haute."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 minutes","explication":"**40 minutes** : 55 − 15 = 40. *In Woche 4 lerne ich länger als in Woche 1.*"},{"cle":{"type":"zone","ids":["m7"]},"explication":"**älterer** : *alt → älter* (comparatif), puis *-er* (terminaison du masculin nominatif après *mein*) : *mein älterer Bruder*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**länger als** : adjectif + **-er**, puis *als*. *wie* sert à l’égalité (*so lang wie*), et *mehr* ne traduit pas « plus » devant un adjectif."},{"cle":{"type":"ordre","ids":["c","b","e","a","d"]},"explication":"**Je mehr Deutsch Paul übt, desto besser spricht er.** Dans la première partie le verbe est rejeté en fin de proposition ; après *desto + comparatif*, il vient aussitôt, devant le sujet."}]$ex$::jsonb),
  ('d6ae8e29-9651-5f5d-afb2-b22204f0127d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les montagnes allemandes","competence":"lire-tableau","situation":"Pour son exposé de géographie, Ben a noté l’altitude de quatre montagnes allemandes.","documents":[{"id":"berge","type":"tableau","titre":"Vier Berge","colonnes":["Berg","Höhe (m)"],"lignes":[["Zugspitze",2962],["Watzmann",2713],["Feldberg",1493],["Brocken",1141]],"enteteLignes":true,"source":"Chiffres arrondis"}],"questions":[{"enonce":"D’après le tableau, quelle phrase est juste ?","aide":"Cherche l’altitude la plus grande.","type":"choix","options":[{"id":"a","texte":"Der Watzmann ist am höchsten"},{"id":"b","texte":"Der Feldberg ist am höchsten"},{"id":"c","texte":"Die Zugspitze ist am höchsten"},{"id":"d","texte":"Der Brocken ist am höchsten"}],"multiple":false},{"enonce":"Complète : « Le Brocken est le plus bas des quatre. »","aide":"Après *g*, pas de *e* de liaison : adjectif + -sten.","type":"trous","segments":["Der Brocken ist am ",0,"."],"banque":["niedrigsten","niedrigstes","niedrigesten","niedrigste"]},{"enonce":"Complète : « La Zugspitze est la plus haute montagne. » (devant un nom)","aide":"Devant un nom, le superlatif se décline : article + -ste.","type":"trous","segments":["Die Zugspitze ist der ",0," Berg."],"banque":["höchsten","höchste","hohe","am höchsten"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"**Die Zugspitze ist am höchsten** : 2 962 m, la plus haute des quatre. Attribut : forme figée *am … -sten*."},{"cle":{"type":"trous","trous":[["niedrigsten"]]},"affichage":"niedrigsten","explication":"**Der Brocken ist am niedrigsten** : *niedrig* + **-sten** ; pas de *e* de liaison, car il ne finit ni par d, t, s, ß, z ni sch."},{"cle":{"type":"trous","trous":[["hochste"]]},"affichage":"höchste","explication":"**der höchste Berg** : devant un nom, *der* + superlatif en **-ste** ; *hoch* perd son *c* et prend l’Umlaut."}]$ex$::jsonb),
  ('d6ae8e29-9651-5f5d-afb2-b22204f0127d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Mon sport préféré","competence":"manier-langue","situation":"Mia et Jan discutent de sport. Leurs messages contiennent deux sortes de superlatifs : l’un est figé, l’autre se décline.","documents":[{"id":"sport","type":"dialogue","modele":"sms","titre":"Sport und Freizeit","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Welcher Sport gefällt dir am besten?"},{"qui":"Jan","texte":"Am liebsten spiele ich Fußball. Tim ist der beste Spieler unserer Klasse."},{"qui":"Mia","texte":"Ich schwimme am schnellsten in der Gruppe."},{"qui":"Jan","texte":"Und Opa? Er ist am ältesten, aber er läuft jeden Tag."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le superlatif qui se décline parce qu’il est devant un nom.","aide":"Il est précédé de *der* et suivi de *Spieler*.","type":"zone","document":"sport","multiple":false},{"enonce":"Touche le superlatif figé qui décrit la façon de nager de Mia.","aide":"Il suit « am ».","type":"zone","document":"sport","multiple":false},{"enonce":"Range chaque phrase selon la forme du superlatif.","aide":"Cherche si un nom suit le superlatif.","type":"categories","categories":[{"id":"c0","texte":"am + -sten (figé)"},{"id":"c1","texte":"article + -ste (décliné)"}],"items":[{"id":"i0","texte":"Das beste Eis kostet drei Euro."},{"id":"i1","texte":"Das schönste Lied kommt jetzt."},{"id":"i2","texte":"Das Eis ist am besten."},{"id":"i3","texte":"Er singt am schönsten."}]},{"enonce":"Complète : « Juillet est le mois le plus chaud. »","aide":"Après *ß*, on intercale un *e* pour pouvoir prononcer.","type":"trous","segments":["Der Juli ist am ",0,"."],"banque":["heißesten","heißten","heißestes","heißsten"]},{"enonce":"Remets en ordre : « Ce que je préfère, c’est manger de la pizza. » La phrase commence par Am liebsten.","aide":"Le verbe est en deuxième position, avant le sujet.","type":"ordre","items":[{"id":"a","texte":"Pizza"},{"id":"b","texte":"Am liebsten"},{"id":"c","texte":"ich"},{"id":"d","texte":"esse"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**beste** : *der beste Spieler*. Devant un nom, on emploie l’article et la forme en **-ste**, qui se décline."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**schnellsten** : *am schnellsten* est la forme figée, utilisée avec un verbe : elle ne se décline pas."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Avec *sein* ou un verbe (*ist am besten*, *singt am schönsten*), la forme est figée en *am … -sten*. Devant un nom (*das beste Eis*), elle se décline."},{"cle":{"type":"trous","trous":[["heissesten"]]},"affichage":"heißesten","explication":"**am heißesten** : *heiß* finit par ß, donc on ajoute un *e* de liaison avant *-sten*."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"**Am liebsten esse ich Pizza.** *am liebsten* exprime « ce que je préfère par-dessus tout » ; il occupe la première place, donc *esse* précède *ich*."}]$ex$::jsonb),
  ('d6ae8e29-9651-5f5d-afb2-b22204f0127d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Records allemands","competence":"argumenter","situation":"Un jeune Français écrit à Tim depuis l’Allemagne. Il a noté le nombre d’habitants de quatre villes et raconte son voyage.","documents":[{"id":"staedte","type":"tableau","titre":"Vier Städte","colonnes":["Stadt","Einwohner (Millionen)"],"lignes":[["Berlin","3,7"],["Hamburg","1,9"],["München","1,5"],["Köln","1,1"]],"enteteLignes":true,"source":"Chiffres arrondis"},{"id":"reise","type":"texte","genre":"lettre","titre":"Hallo Tim","blocs":["Ich bin in Deutschland! Berlin ist die größte Stadt des Landes. München gefällt mir gut, aber Hamburg ist größer. Von allen Städten besuche ich Köln am liebsten."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche le superlatif décliné devant un nom.","aide":"Il est précédé de *die*.","type":"zone","document":"reise","multiple":false},{"enonce":"Combien de millions d’habitants de plus Berlin compte-t-elle que Hambourg ?","aide":"Soustrais 1,9 à 3,7.","type":"nombre","unite":"millions"},{"enonce":"Quelle phrase est juste d’après le tableau ?","aide":"Cherche la ville qui a le moins d’habitants.","type":"choix","options":[{"id":"a","texte":"Berlin ist die kleinste der vier Städte"},{"id":"b","texte":"München ist am größten von allen"},{"id":"c","texte":"Hamburg ist die größte der vier Städte"},{"id":"d","texte":"Köln ist die kleinste der vier Städte"}],"multiple":false},{"enonce":"Complète : « La plus petite ville des quatre est Cologne. »","aide":"Devant un nom, le superlatif se décline.","type":"trous","segments":["Die ",0," Stadt der vier ist Köln."],"banque":["kleinste","kleiner","am kleinsten","kleinsten"]},{"enonce":"Remets en ordre : « Hambourg me plaît le plus. » La phrase commence par Hamburg.","aide":"*gefallen* est en deuxième position, puis le datif *mir*.","type":"ordre","items":[{"id":"a","texte":"gefällt"},{"id":"b","texte":"mir"},{"id":"c","texte":"am besten"},{"id":"d","texte":"Hamburg"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**größte** : *die größte Stadt*. Devant un nom, on emploie article + superlatif en **-ste** ; *groß* n’a pas de *e* de liaison."},{"cle":{"type":"nombre","valeur":1.8,"tolerance":0},"affichage":"1,8 millions","explication":"**1,8 million** : 3,7 − 1,9 = 1,8."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Köln ist die kleinste der vier Städte** : 1,1 million, c’est le plus petit nombre. Le complément se dit avec *von* ou, ici, *der vier Städte*."},{"cle":{"type":"trous","trous":[["kleinste"]]},"affichage":"kleinste","explication":"**Die kleinste Stadt** : devant un nom, article + adjectif + **-ste**."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**Hamburg gefällt mir am besten.** *gut → besser → am besten* : avec un verbe, on emploie la forme figée *am besten*."}]$ex$::jsonb),
  ('8cb594f7-69cf-5649-aae3-a6b786833efe'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un goûter pour Opa","competence":"comprendre-langue","situation":"Jule prépare l’anniversaire de son grand-père. Son petit mot contient plusieurs prépositions qu’il faut savoir reconnaître.","documents":[{"id":"opa","type":"texte","genre":"lettre","titre":"Opas Geburtstag","blocs":["Morgen hat Opa Geburtstag. Ich kaufe ein Geschenk für meinen Opa. Wir gehen durch den Park und sitzen um einen Tisch. Ohne Oma feiern wir nicht."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre prépositions qui sont toujours suivies de l’accusatif.","aide":"Pense à la liste durch · für · gegen · ohne · um.","type":"zone","document":"opa","multiple":true},{"enonce":"Associe chaque préposition à son sens.","aide":"Retrouve chaque préposition dans le texte.","type":"association","gauche":[{"id":"g0","texte":"durch"},{"id":"g1","texte":"für"},{"id":"g2","texte":"ohne"},{"id":"g3","texte":"um"}],"droite":[{"id":"d0","texte":"sans"},{"id":"d1","texte":"à travers"},{"id":"d2","texte":"pour"},{"id":"d3","texte":"autour de"}]},{"enonce":"Complète : « Le cadeau est pour ma sœur. »","aide":"*für* demande l’accusatif ; *Schwester* est féminin.","type":"trous","segments":["Das Geschenk ist für ",0," Schwester."],"banque":["der","den","die","dem"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m13","m18","m21"]},"explication":"**für**, **durch**, **um** et **ohne** régissent toujours l’accusatif, quel que soit le sens."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"*durch* = à travers, *für* = pour, *ohne* = sans, *um* = autour de."},{"cle":{"type":"trous","trous":[["die"]]},"affichage":"die","explication":"**für die Schwester** : accusatif féminin = *die*."}]$ex$::jsonb),
  ('8cb594f7-69cf-5649-aae3-a6b786833efe'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Rendez-vous au cinéma","competence":"analyser-document","situation":"Ben et Mia organisent une soirée cinéma. Pour s’y retrouver, ils doivent distinguer l’heure approximative de l’heure précise.","documents":[{"id":"kino","type":"dialogue","modele":"sms","titre":"Heute Abend","participants":[{"nom":"Ben","emoji":"👧","cote":"gauche"},{"nom":"Mia","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Wann treffen wir uns heute?"},{"qui":"Mia","texte":"Gegen vier. Der Film beginnt um 18 Uhr."},{"qui":"Ben","texte":"Super. Ich komme ohne Marie, sie ist krank."},{"qui":"Mia","texte":"Schade! Dann kaufe ich Popcorn für uns beide."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui donne une heure approximative, « vers quatre heures ».","aide":"Ce n’est pas celle du film.","type":"zone","document":"kino","multiple":false},{"enonce":"Touche la préposition qui donne une heure précise.","aide":"Elle est devant « 18 Uhr ».","type":"zone","document":"kino","multiple":false},{"enonce":"À quelle heure exacte commence le film ? (en heures, sur 24 h)","aide":"Cherche la préposition de l’heure précise.","type":"nombre","unite":"Uhr"},{"enonce":"Complète : « Nous jouons sans elle. » (Marie)","aide":"*ohne* est suivi de l’accusatif.","type":"trous","segments":["Wir spielen ohne ",0,"."],"banque":["sie","es","ihr","ihm"]},{"enonce":"Remets en ordre : « Nous traversons le parc. » La phrase commence par Wir.","aide":"*durch* est suivi de l’accusatif.","type":"ordre","items":[{"id":"a","texte":"den Park"},{"id":"b","texte":"durch"},{"id":"c","texte":"gehen"},{"id":"d","texte":"Wir"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**Gegen** : *gegen vier* = « vers quatre heures »."},{"cle":{"type":"zone","ids":["m10"]},"explication":"**um** : *um 18 Uhr* = « à 18 h pile »."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18 Uhr","explication":"**18 Uhr** : le film commence *um 18 Uhr*, donc à l’heure précise de 18 h."},{"cle":{"type":"trous","trous":[["sie"]]},"affichage":"sie","explication":"**ohne sie** : *ohne* demande l’accusatif, et le pronom de « elle » à l’accusatif est *sie*."},{"cle":{"type":"ordre","ids":["d","c","b","a"]},"explication":"**Wir gehen durch den Park.** *durch* + accusatif masculin (*den*)."}]$ex$::jsonb),
  ('8cb594f7-69cf-5649-aae3-a6b786833efe'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Le rallye de la ville","competence":"analyser-document","situation":"Pour la semaine d’intégration, les élèves de 3e font un rallye dans la ville. La feuille de route précise l’itinéraire ; Jule et Ole échangent des messages à la veille du départ.","documents":[{"id":"rallye","type":"fiche","modele":"affiche","entete":"Stadtrallye","sousTitre":"Samstag, 9 Uhr","emoji":"🗺️","lignes":[{"texte":"1 · Gehen Sie durch den Park.","id":"z1"},{"texte":"2 · Laufen Sie die Straße entlang.","id":"z2"},{"texte":"3 · Gehen Sie um die Kirche.","id":"z3"},{"texte":"4 · Treffpunkt: gegen 15 Uhr am Brunnen.","id":"z4"}],"pied":"Feuille écrite pour l’exercice","teinte":"bleu"},{"id":"jule","type":"dialogue","modele":"sms","titre":"Vor dem Rallye","participants":[{"nom":"Jule","emoji":"👧","cote":"gauche"},{"nom":"Ole","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jule","texte":"Kommst du mit dem Auto?"},{"qui":"Ole","texte":"Nein, ich komme ohne Auto, mit dem Bus."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui impose toujours l’accusatif.","aide":"L’autre préposition est suivie du datif.","type":"zone","document":"jule","multiple":false},{"enonce":"Touche la ligne où la préposition se place après le nom.","aide":"Cherche le mot qui veut dire « le long de ».","type":"zone","document":"rallye","multiple":false},{"enonce":"Complète : « Nous marchons autour de la fontaine et à travers la porte. »","aide":"*um* et *durch* demandent l’accusatif ; regarde le genre de *Brunnen* et de *Tür*.","type":"trous","segments":["Wir laufen um ",0," Brunnen und gehen durch ",1," Tür."],"banque":["die","den","dem","das"]},{"enonce":"Remets en ordre : « Nous longeons la rue. » La phrase commence par Wir.","aide":"*entlang* est placé après le nom.","type":"ordre","items":[{"id":"a","texte":"entlang"},{"id":"b","texte":"Wir"},{"id":"c","texte":"gehen"},{"id":"d","texte":"die Straße"}]},{"enonce":"Que signifie « Treffpunkt : gegen 15 Uhr » sur la feuille ?","aide":"Compare avec *um 15 Uhr*.","type":"choix","options":[{"id":"a","texte":"On se retrouve à 15 heures pile"},{"id":"b","texte":"On se retrouve avant 15 heures"},{"id":"c","texte":"On se retrouve après 15 heures"},{"id":"d","texte":"On se retrouve vers 15 heures"}],"multiple":false},{"enonce":"Complète : « Je vais à la gare pour chercher mon grand-père. »","aide":"Devant un verbe à l’infinitif, *für* est impossible.","type":"trous","segments":["Ich fahre zum Bahnhof, ",0," Opa abzuholen."],"banque":["ohne","um","für","durch"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**ohne** régit toujours l’accusatif ; *mit* régit toujours le datif."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Ligne 2** : *die Straße entlang*. *entlang* se place **après** le nom et veut dire « le long de »."},{"cle":{"type":"trous","trous":[["den"],["die"]]},"affichage":"den · die","explication":"**um den Brunnen** (masculin) et **durch die Tür** (féminin) : accusatif après *um* et *durch*."},{"cle":{"type":"ordre","ids":["b","c","d","a"]},"explication":"**Wir gehen die Straße entlang.** Avec *entlang* en postposition, le nom est à l’accusatif : *die Straße*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Vers 15 heures** : *gegen* donne une heure approximative ; *um* donnerait l’heure précise."},{"cle":{"type":"trous","trous":[["um"]]},"affichage":"um","explication":"**um … zu** : « pour + infinitif » se dit *um … zu*. *für* introduit un groupe nominal, jamais un verbe."}]$ex$::jsonb),
  ('fd09c791-70ea-5173-911b-70d1064fb715'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le quotidien de Nele","competence":"comprendre-langue","situation":"Nele se présente à sa correspondante française. Elle raconte où elle habite, comment elle va à l’école et d’où vient son amie.","documents":[{"id":"nele","type":"texte","genre":"recit","titre":"Mein Alltag","blocs":["Ich wohne bei meinen Eltern. Ich fahre mit dem Bus zur Schule. Meine Freundin kommt aus der Schweiz. Sie lernt seit einem Jahr Deutsch."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les cinq prépositions qui sont toujours suivies du datif.","aide":"Pense à la formule aus · bei · mit · nach · seit · von · zu.","type":"zone","document":"nele","multiple":true},{"enonce":"Associe chaque préposition à son sens.","aide":"Retrouve chaque préposition dans le texte de Nele.","type":"association","gauche":[{"id":"g0","texte":"aus"},{"id":"g1","texte":"bei"},{"id":"g2","texte":"mit"},{"id":"g3","texte":"seit"}],"droite":[{"id":"d0","texte":"avec, en (transport)"},{"id":"d1","texte":"chez"},{"id":"d2","texte":"en provenance de"},{"id":"d3","texte":"depuis"}]},{"enonce":"Complète : « Il va en train et habite chez sa tante. »","aide":"Après ces prépositions, le datif : *der Zug* est masculin, *die Tante* féminin.","type":"trous","segments":["Er fährt mit ",0," Zug und wohnt bei ",1," Tante."],"banque":["den","seiner","seine","dem"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m7","m10","m15","m20"]},"explication":"**bei**, **mit**, **zur** (= *zu der*), **aus** et **seit** régissent toujours le datif."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"*aus* = hors de, *bei* = chez, *mit* = avec (ou « en » avec un moyen de transport), *seit* = depuis."},{"cle":{"type":"trous","trous":[["dem"],["seiner"]]},"affichage":"dem · seiner","explication":"**mit dem Zug** (masculin datif : *dem*) et **bei seiner Tante** (féminin datif : *-er*)."}]$ex$::jsonb),
  ('fd09c791-70ea-5173-911b-70d1064fb715'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où est Mara ?","competence":"manier-langue","situation":"Lukas cherche Mara, qui enchaîne plusieurs rendez-vous. Dans leurs messages, plusieurs prépositions sont contractées avec l’article.","documents":[{"id":"mara","type":"dialogue","modele":"sms","titre":"Wo bist du?","participants":[{"nom":"Lukas","emoji":"👧","cote":"gauche"},{"nom":"Mara","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lukas","texte":"Wo bist du?"},{"qui":"Mara","texte":"Ich bin beim Arzt. Danach gehe ich zur Apotheke und dann zum Bahnhof."},{"qui":"Lukas","texte":"Kommst du vom Arzt direkt zu mir?"},{"qui":"Mara","texte":"Nein, erst nach dem Essen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les quatre prépositions contractées avec l’article.","aide":"Elles se terminent par -m ou -r et remplacent *bei dem*, *zu der*, *zu dem*, *von dem*.","type":"zone","document":"mara","multiple":true},{"enonce":"Associe chaque forme pleine à sa contraction.","aide":"Garde la même préposition et fusionne-la avec l’article.","type":"association","gauche":[{"id":"g0","texte":"zu der"},{"id":"g1","texte":"zu dem"},{"id":"g2","texte":"bei dem"},{"id":"g3","texte":"von dem"}],"droite":[{"id":"d0","texte":"beim"},{"id":"d1","texte":"zum"},{"id":"d2","texte":"vom"},{"id":"d3","texte":"zur"}]},{"enonce":"Complète : « Nous allons à la piscine. »","aide":"*Schwimmbad* est neutre.","type":"trous","segments":["Wir gehen ",0," Schwimmbad."],"banque":["zum","beim","vom","zur"]},{"enonce":"Remets en ordre : « Après le repas, je vais à la pharmacie. » La phrase commence par Nach dem Essen.","aide":"Le groupe de temps est en tête, donc le verbe passe avant le sujet.","type":"ordre","items":[{"id":"a","texte":"gehe"},{"id":"b","texte":"Nach dem Essen"},{"id":"c","texte":"zur Apotheke"},{"id":"d","texte":"ich"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m10","m14","m18"]},"explication":"**beim**, **zur**, **zum** et **vom** sont des contractions obligatoires dans l’usage courant."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"*zu der → zur*, *zu dem → zum*, *bei dem → beim*, *von dem → vom*."},{"cle":{"type":"trous","trous":[["zum"]]},"affichage":"zum","explication":"**zum Schwimmbad** : *zu dem* se contracte en *zum* (masculin et neutre)."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**Nach dem Essen gehe ich zur Apotheke.** *nach* + datif ; le verbe reste en deuxième position."}]$ex$::jsonb),
  ('fd09c791-70ea-5173-911b-70d1064fb715'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Une carte postale de Vienne et de Suisse","competence":"argumenter","situation":"Jana prépare un voyage en Autriche puis en Suisse. Elle l’annonce à sa grand-mère et lui répond au sujet de son allemand.","documents":[{"id":"reise","type":"texte","genre":"lettre","titre":"Hallo Oma","blocs":["Morgen fahre ich mit dem Zug nach Wien. Am Samstag fliege ich in die Schweiz, zu meinem Onkel. Ich bleibe bei ihm bis Montag. Die Schokolade für dich ist aus der Schweiz."],"source":"Lettre écrite pour l’exercice"},{"id":"oma","type":"dialogue","modele":"sms","titre":"Oma fragt","participants":[{"nom":"Oma","emoji":"👧","cote":"gauche"},{"nom":"Jana","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Oma","texte":"Wie lange lernst du schon Deutsch?"},{"qui":"Jana","texte":"Ich lerne seit zwei Jahren Deutsch."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui précède une ville sans article.","aide":"Wien est un nom de ville.","type":"zone","document":"reise","multiple":false},{"enonce":"Touche la préposition employée devant un pays avec article.","aide":"*die Schweiz* a un article.","type":"zone","document":"reise","multiple":false},{"enonce":"Touche la préposition qui précède une personne comme but du voyage.","aide":"Elle est suivie de *meinem Onkel*.","type":"zone","document":"reise","multiple":false},{"enonce":"Complète : « Je vais à Berlin, en Turquie et chez ma tante. »","aide":"Ville sans article, pays avec article, personne : trois prépositions différentes.","type":"trous","segments":["Ich fahre ",0," Berlin, ",1," die Türkei und ",2," meiner Tante."],"banque":["nach","in","aus","zu","bei"]},{"enonce":"Touche la préposition qui exprime « depuis » dans la réponse de Jana.","aide":"Elle est devant « zwei Jahren ».","type":"zone","document":"oma","multiple":false},{"enonce":"Comment dit-on « Je connais Marie depuis deux ans » ?","aide":"Comme dans la réponse de Jana, un fait qui dure encore s’exprime avec le même temps.","type":"choix","options":[{"id":"a","texte":"Ich werde Marie seit zwei Jahren kennen"},{"id":"b","texte":"Ich kannte Marie seit zwei Jahren"},{"id":"c","texte":"Ich kenne Marie seit zwei Jahren"},{"id":"d","texte":"Ich habe Marie seit zwei Jahren gekannt"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**nach** : *nach Wien*. Les villes et les pays sans article se disent avec *nach*."},{"cle":{"type":"zone","ids":["m12"]},"explication":"**in** : *in die Schweiz* (accusatif). Un pays avec article demande *in* + accusatif."},{"cle":{"type":"zone","ids":["m15"]},"explication":"**zu** : *zu meinem Onkel*. Pour aller chez quelqu’un, on emploie *zu* + datif."},{"cle":{"type":"trous","trous":[["nach"],["in"],["zu"]]},"affichage":"nach · in · zu","explication":"**nach Berlin** (ville sans article), **in die Türkei** (pays avec article, accusatif), **zu meiner Tante** (personne, datif)."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**seit** : *seit zwei Jahren* = « depuis deux ans », avec un datif."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Ich kenne Marie seit zwei Jahren** : avec *seit*, l’allemand emploie le **présent** pour une situation qui dure encore."}]$ex$::jsonb),
  ('cc00a503-7d91-51e2-8703-5e8a4e2089c1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le désordre de Lena","competence":"comprendre-langue","situation":"Lena range sa chambre avant de partir. Un court texte raconte où se trouvent ses affaires et où elle les met.","documents":[{"id":"zimmer","type":"texte","genre":"recit","titre":"Lenas Zimmer","blocs":["Das Buch liegt auf dem Tisch. Eine Katze sitzt unter dem Stuhl. Lena legt ein Heft auf den Tisch. Dann geht sie in die Küche."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux articles au datif : ils répondent à la question « wo ? ».","aide":"Le livre et la chatte ne bougent pas.","type":"zone","document":"zimmer","multiple":true},{"enonce":"Touche les deux articles à l’accusatif : ils répondent à la question « wohin ? ».","aide":"Lena met le cahier quelque part et se déplace.","type":"zone","document":"zimmer","multiple":true},{"enonce":"Complète : « Le téléphone est sur le lit. »","aide":"*liegt* indique un lieu, pas un déplacement.","type":"trous","segments":["Das Handy liegt auf ",0," Bett."],"banque":["dem","den","das","die"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m10"]},"explication":"**dem** (deux fois) : *auf dem Tisch*, *unter dem Stuhl* décrivent un lieu où l’on est : datif."},{"cle":{"type":"zone","ids":["m17","m23"]},"explication":"**den** et **die** : *auf den Tisch*, *in die Küche* disent où l’on va ou où l’on pose quelque chose : accusatif."},{"cle":{"type":"trous","trous":[["dem"]]},"affichage":"dem","explication":"**auf dem Bett** : *wo ?* donne le datif ; *Bett* est neutre, donc *dem*."}]$ex$::jsonb),
  ('cc00a503-7d91-51e2-8703-5e8a4e2089c1'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le déménagement","competence":"manier-langue","situation":"Eva et Max emménagent dans un nouvel appartement. Chaque objet doit être posé au bon endroit : ils parlent tantôt d’un mouvement, tantôt d’un lieu.","documents":[{"id":"umzug","type":"dialogue","modele":"sms","titre":"Umzug","participants":[{"nom":"Eva","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Eva","texte":"Wohin stelle ich die Lampe?"},{"qui":"Max","texte":"Stell sie bitte auf den Schreibtisch. Die Pflanze steht schon neben dem Fenster."},{"qui":"Eva","texte":"Und der Teppich? Ich lege ihn vor das Sofa."},{"qui":"Max","texte":"Gut. Dann sitzt die Katze bald auf dem Teppich."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux articles au datif : ils répondent à « wo ? ».","aide":"Ils décrivent un état, pas un mouvement.","type":"zone","document":"umzug","multiple":true},{"enonce":"Range chaque verbe : action (accusatif) ou état (datif) ?","aide":"Les verbes en *-en* qui commencent par *st-*, *l-*, *s-* vont par paires : un pour l’action, un pour l’état.","type":"categories","categories":[{"id":"c0","texte":"Action → accusatif (wohin ?)"},{"id":"c1","texte":"État → datif (wo ?)"}],"items":[{"id":"i0","texte":"stehen"},{"id":"i1","texte":"sitzen"},{"id":"i2","texte":"setzen"},{"id":"i3","texte":"legen"},{"id":"i4","texte":"stellen"},{"id":"i5","texte":"liegen"}]},{"enonce":"Complète : « Je pose le livre sur la table. Le livre est sur la table. »","aide":"Premier trou : action (*legen*) ; deuxième trou : état (*liegen*).","type":"trous","segments":["Ich ",0," das Buch auf den Tisch. Das Buch ",1," auf dem Tisch."],"banque":["lege","liege","legt","liegt"]},{"enonce":"Associe chaque forme pleine à sa contraction.","aide":"*das* devient *-s*, *dem* devient *-m*.","type":"association","gauche":[{"id":"g0","texte":"in das"},{"id":"g1","texte":"in dem"},{"id":"g2","texte":"an dem"},{"id":"g3","texte":"auf das"}],"droite":[{"id":"d0","texte":"aufs"},{"id":"d1","texte":"im"},{"id":"d2","texte":"ins"},{"id":"d3","texte":"am"}]},{"enonce":"Remets en ordre : « J’assieds l’enfant sur la chaise. » La phrase commence par Ich.","aide":"*setzen* indique un mouvement : accusatif.","type":"ordre","items":[{"id":"a","texte":"setze"},{"id":"b","texte":"auf den Stuhl"},{"id":"c","texte":"das Kind"},{"id":"d","texte":"Ich"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m34"]},"explication":"**dem** (deux fois) : *neben dem Fenster* (où la plante se trouve) et *auf dem Teppich* (où la chatte sera) sont des lieux : datif."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"*stellen / legen / setzen* décrivent une **action** (on déplace quelque chose : accusatif) ; *stehen / liegen / sitzen* décrivent un **état** (datif)."},{"cle":{"type":"trous","trous":[["lege"],["liegt"]]},"affichage":"lege · liegt","explication":"**Ich lege** (action, accusatif : *auf den Tisch*) puis **liegt** (état, datif : *auf dem Tisch*)."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"*in das → ins*, *in dem → im*, *an dem → am*, *auf das → aufs*."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"**Ich setze das Kind auf den Stuhl.** *setzen* (action) appelle *auf* + accusatif."}]$ex$::jsonb),
  ('cc00a503-7d91-51e2-8703-5e8a4e2089c1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Emménager, étape par étape","competence":"raisonner","situation":"Anna décrit sa nouvelle chambre dans une lettre ; elle échange aussi des messages avec son père, qui déplace les meubles. Il faut dire à chaque fois s’il y a mouvement ou non.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Hallo Mia","blocs":["Heute ziehe ich um! Das Sofa steht jetzt im Wohnzimmer. Den Tisch stelle ich vor das Fenster. Neben dem Sofa liegt der Teppich. Über dem Tisch hängt die Lampe. Morgen hänge ich ein Bild an die Wand."],"source":"Lettre écrite pour l’exercice"},{"id":"papa","type":"dialogue","modele":"sms","titre":"Mit Papa","participants":[{"nom":"Papa","emoji":"👧","cote":"gauche"},{"nom":"Anna","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"Wo soll ich den Schrank hinstellen?"},{"qui":"Anna","texte":"Stell ihn neben die Tür."},{"qui":"Papa","texte":"Er steht jetzt neben der Tür. Und die Kisten?"},{"qui":"Anna","texte":"Leg sie unter das Bett. Dann liegen sie sicher unter dem Bett."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux prépositions qui expriment un déplacement : elles sont suivies de l’accusatif.","aide":"Anna pose ou accroche quelque chose quelque part.","type":"zone","document":"brief","multiple":true},{"enonce":"Touche les trois prépositions qui expriment un lieu : elles sont suivies du datif.","aide":"Le sofa, le tapis et la lampe sont déjà en place.","type":"zone","document":"brief","multiple":true},{"enonce":"Range chaque phrase du dialogue : mouvement (wohin ?) ou lieu (wo ?).","aide":"Repère le verbe : *stellen* et *legen* disent un geste, *stehen* et *liegen* un état.","type":"categories","categories":[{"id":"c0","texte":"Mouvement → accusatif (wohin ?)"},{"id":"c1","texte":"Lieu → datif (wo ?)"}],"items":[{"id":"i0","texte":"Sie liegen unter dem Bett."},{"id":"i1","texte":"Er steht jetzt neben der Tür."},{"id":"i2","texte":"Stell ihn neben die Tür."},{"id":"i3","texte":"Leg sie unter das Bett."}]},{"enonce":"Complète : « Papa pose l’armoire à côté de la porte. Maintenant elle est à côté de la porte. »","aide":"Premier trou : action ; deuxième trou : état.","type":"trous","segments":["Papa ",0," den Schrank neben die Tür. Jetzt ",1," er neben der Tür."],"banque":["stelle","steht","stehen","stellt"]},{"enonce":"Remets en ordre : « Je mets les caisses sous le lit. » La phrase commence par Ich.","aide":"Il y a un mouvement : accusatif.","type":"ordre","items":[{"id":"a","texte":"die Kisten"},{"id":"b","texte":"Ich"},{"id":"c","texte":"lege"},{"id":"d","texte":"unter das Bett"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m34"]},"explication":"**vor** (*stelle ich vor das Fenster*) et **an** (*hänge ich an die Wand*) expriment un mouvement : accusatif."},{"cle":{"type":"zone","ids":["m8","m17","m23"]},"explication":"**im** (= *in dem*), **Neben** et **Über** décrivent où sont les objets : datif."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"*Stell ihn neben die Tür* et *Leg sie unter das Bett* : mouvement, accusatif (*die*, *das*). *steht neben der Tür* et *liegen unter dem Bett* : lieu, datif (*der*, *dem*)."},{"cle":{"type":"trous","trous":[["stellt"],["steht"]]},"affichage":"stellt · steht","explication":"**stellt** (action, avec accusatif : *neben die Tür*) puis **steht** (état, avec datif : *neben der Tür*)."},{"cle":{"type":"ordre","ids":["b","c","a","d"]},"explication":"**Ich lege die Kisten unter das Bett.** *legen* + *unter* + accusatif."}]$ex$::jsonb),
  ('cefc03ac-43b5-5bc8-9ad9-cb5eaae10195'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le week-end de Lena","competence":"comprendre-langue","situation":"Lena raconte son week-end à son correspondant. Son texte relie les phrases avec de petits mots qu’il faut repérer.","documents":[{"id":"wochenende","type":"texte","genre":"recit","titre":"Mein Wochenende","blocs":["Am Samstag bleibe ich zu Hause, denn ich bin müde. Ich lese ein Buch und höre Musik. Am Sonntag gehe ich ins Kino oder ich besuche meine Oma. Das Wetter ist schlecht, aber ich habe gute Laune."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre conjonctions de coordination du texte.","aide":"Elles relient deux éléments de même rang : cause, addition, choix, opposition.","type":"zone","document":"wochenende","multiple":true},{"enonce":"Associe chaque conjonction à son sens.","aide":"Retrouve chaque mot dans le texte de Lena.","type":"association","gauche":[{"id":"g0","texte":"und"},{"id":"g1","texte":"oder"},{"id":"g2","texte":"aber"},{"id":"g3","texte":"denn"}],"droite":[{"id":"d0","texte":"ou"},{"id":"d1","texte":"car"},{"id":"d2","texte":"mais"},{"id":"d3","texte":"et"}]},{"enonce":"Remets en ordre : « Je reste à la maison, car je suis malade. » La phrase commence par Ich bleibe zu Hause.","aide":"Après *denn*, l’ordre est normal : sujet puis verbe.","type":"ordre","items":[{"id":"a","texte":"bin"},{"id":"b","texte":"krank"},{"id":"c","texte":"denn"},{"id":"d","texte":"Ich bleibe zu Hause"},{"id":"e","texte":"ich"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m14","m23","m32"]},"explication":"**denn**, **und**, **oder** et **aber** sont des conjonctions de coordination : elles ne changent pas l’ordre des mots."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"*und* = et, *oder* = ou, *aber* = mais, *denn* = car."},{"cle":{"type":"ordre","ids":["d","c","e","a","b"]},"explication":"**Ich bleibe zu Hause, denn ich bin krank.** *denn* est une coordination : le verbe reste en deuxième position."}]$ex$::jsonb),
  ('cefc03ac-43b5-5bc8-9ad9-cb5eaae10195'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi Ben ne vient pas","competence":"analyser-document","situation":"Ben et Mia parlent d’une fête. Pour expliquer pourquoi il reste chez lui, Ben utilise trois constructions qui disent la même chose, mais pas avec le même ordre des mots.","documents":[{"id":"party","type":"dialogue","modele":"sms","titre":"Die Party","participants":[{"nom":"Ben","emoji":"👧","cote":"gauche"},{"nom":"Mia","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Ich komme nicht zur Party, denn ich bin krank."},{"qui":"Mia","texte":"Schade! Es regnet auch, deshalb bleiben viele zu Hause."},{"qui":"Ben","texte":"Ich bleibe zu Hause, weil ich Fieber habe."},{"qui":"Mia","texte":"Gute Besserung! Ich komme zwar spät, aber ich komme."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction de coordination qui veut dire « car ».","aide":"Le verbe qui suit reste en deuxième position.","type":"zone","document":"party","multiple":false},{"enonce":"Touche la conjonction de subordination : le verbe est envoyé à la fin.","aide":"Dans la phrase, le verbe *habe* est le dernier mot.","type":"zone","document":"party","multiple":false},{"enonce":"Touche l’adverbe de liaison qui provoque l’inversion du verbe et du sujet.","aide":"Le verbe *bleiben* précède son sujet.","type":"zone","document":"party","multiple":false},{"enonce":"Range chaque phrase selon la place du verbe.","aide":"Regarde la position du verbe après le mot de liaison.","type":"categories","categories":[{"id":"c0","texte":"Verbe en 2e position (coordination)"},{"id":"c1","texte":"Verbe à la fin (subordination)"},{"id":"c2","texte":"Inversion (adverbe de liaison)"}],"items":[{"id":"i0","texte":"Ich bin krank, deshalb bleibe ich."},{"id":"i1","texte":"Ich bleibe, weil ich krank bin."},{"id":"i2","texte":"Ich bin müde, aber ich komme."},{"id":"i3","texte":"Ich bleibe, denn ich bin krank."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**denn** : *denn ich bin krank*. Le verbe reste en deuxième position."},{"cle":{"type":"zone","ids":["m22"]},"explication":"**weil** : *weil ich Fieber habe*. Après *weil*, le verbe conjugué se place à la fin."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**deshalb** : *deshalb bleiben viele zu Hause*. L’adverbe occupe la première place, donc le verbe passe devant le sujet."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c0"}},"explication":"*denn* et *aber* ne changent rien : sujet puis verbe. *weil* envoie le verbe à la fin. *deshalb* occupe la première place : le verbe passe devant le sujet."}]$ex$::jsonb),
  ('cefc03ac-43b5-5bc8-9ad9-cb5eaae10195'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Le courriel de la classe de Berlin","competence":"argumenter","situation":"Paul est en voyage scolaire à Berlin. Pour rassurer ses parents, il leur envoie un courriel soigné qui joue avec les couples de conjonctions.","documents":[{"id":"klassenfahrt","type":"texte","genre":"lettre","titre":"Liebe Eltern","blocs":["Die Klassenfahrt nach Berlin ist nicht nur lustig, sondern auch lehrreich. Das Hotel ist zwar klein, aber sehr sauber. Wir haben weder Handy noch Computer im Zimmer. Wir fahren nicht mit dem Bus, sondern mit dem Zug. Entweder gehen wir ins Museum oder wir besuchen den Reichstag."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux « sondern » du courriel.","aide":"Ils suivent une négation (*nicht nur*, *nicht*).","type":"zone","document":"klassenfahrt","multiple":true},{"enonce":"Touche le couple qui veut dire « ni… ni ».","aide":"La phrase est déjà négative : pas de *nicht*.","type":"zone","document":"klassenfahrt","multiple":true},{"enonce":"Associe chaque couple à son sens.","aide":"Pense au courriel de Paul pour les deux premiers.","type":"association","gauche":[{"id":"g0","texte":"entweder … oder"},{"id":"g1","texte":"weder … noch"},{"id":"g2","texte":"sowohl … als auch"},{"id":"g3","texte":"zwar … aber"}],"droite":[{"id":"d0","texte":"certes … mais"},{"id":"d1","texte":"aussi bien … que"},{"id":"d2","texte":"ou bien … ou bien"},{"id":"d3","texte":"ni … ni"}]},{"enonce":"Pourquoi écrit-on « nicht mit dem Bus, sondern mit dem Zug » et non « aber » ?","aide":"Regarde le mot qui précède la virgule dans la première partie.","type":"choix","options":[{"id":"a","texte":"Aber est interdit devant une préposition"},{"id":"b","texte":"La virgule est supprimée avec sondern"},{"id":"c","texte":"La première partie est négative et on la rectifie"},{"id":"d","texte":"Sondern est plus poli que aber"}],"multiple":false},{"enonce":"Remets en ordre : « Il n’est pas seulement intelligent, mais aussi gentil. » La phrase commence par Er.","aide":"Le verbe est en deuxième position, puis le couple *nicht nur … sondern auch*.","type":"ordre","items":[{"id":"a","texte":"nicht nur klug"},{"id":"b","texte":"sondern"},{"id":"c","texte":"ist"},{"id":"d","texte":"auch nett"},{"id":"e","texte":"Er"}]},{"enonce":"Complète : « Je n’ai ni temps ni argent. »","aide":"Le couple veut dire « ni… ni ».","type":"trous","segments":["Ich habe ",0," Zeit ",1," Geld."],"banque":["nicht","entweder","weder","noch"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m33"]},"explication":"**sondern** (deux fois) : après une négation, il rectifie ou ajoute (*nicht nur … sondern auch*, *nicht mit dem Bus, sondern mit dem Zug*)."},{"cle":{"type":"zone","ids":["m21","m23"]},"explication":"**weder … noch** : *weder Handy noch Computer*. Ce couple contient déjà la négation."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"*entweder … oder* = ou bien … ou bien ; *weder … noch* = ni … ni ; *sowohl … als auch* = aussi bien … que ; *zwar … aber* = certes … mais."},{"cle":{"type":"choix","ids":["c"]},"explication":"**La première partie est négative (*nicht*) et la seconde la rectifie** : c’est le cas de *sondern*. *aber* s’emploie sans négation ou pour une simple opposition."},{"cle":{"type":"ordre","ids":["e","c","a","b","d"]},"explication":"**Er ist nicht nur klug, sondern auch nett.** Le couple *nicht nur … sondern auch* ne modifie pas la place du verbe."},{"cle":{"type":"trous","trous":[["weder"],["noch"]]},"affichage":"weder · noch","explication":"**Ich habe weder Zeit noch Geld.** Le couple *weder … noch* est déjà négatif : on n’ajoute pas *nicht*."}]$ex$::jsonb),
  ('3fbce238-20b2-58e6-8151-86349b454de2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"D’où viens-tu ? Où vas-tu ?","competence":"comprendre-langue","situation":"Lena, une jeune Française, bavarde avec Tom sur le quai d’une gare allemande. Il lui demande d’où elle vient et où elle va.","documents":[{"id":"bahnhof","type":"dialogue","modele":"sms","titre":"Am Bahnhof","participants":[{"nom":"Tom","emoji":"👧","cote":"gauche"},{"nom":"Lena","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Woher kommst du?"},{"qui":"Lena","texte":"Ich komme aus Frankreich. Jetzt wohne ich in Lyon."},{"qui":"Tom","texte":"Und wohin fährst du morgen?"},{"qui":"Lena","texte":"Ich fahre nach Berlin."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui dit d’où vient Lena.","aide":"Elle est suivie de *Frankreich*.","type":"zone","document":"bahnhof","multiple":false},{"enonce":"Touche la préposition qui dit où Lena va, devant une ville sans article.","aide":"Elle est devant *Berlin*.","type":"zone","document":"bahnhof","multiple":false},{"enonce":"Associe chaque question à son sens.","aide":"*hin* s’éloigne du locuteur, *her* se rapproche.","type":"association","gauche":[{"id":"g0","texte":"wo ?"},{"id":"g1","texte":"wohin ?"},{"id":"g2","texte":"woher ?"}],"droite":[{"id":"d0","texte":"l’origine (d’où)"},{"id":"d1","texte":"la localisation (où)"},{"id":"d2","texte":"la destination (vers où)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**aus** : *Ich komme aus Frankreich*. Il répond à la question *woher ?*."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**nach** : *nach Berlin*. Il répond à la question *wohin ?*, pour une ville ou un pays sans article."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"*wo ?* = où l’on est ; *wohin ?* = où l’on va ; *woher ?* = d’où l’on vient."}]$ex$::jsonb),
  ('3fbce238-20b2-58e6-8151-86349b454de2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Avec ou sans mouvement ?","competence":"manier-langue","situation":"Lea écrit à Tom, qui court d’un rendez-vous à l’autre. Selon qu’il est quelque part ou qu’il s’y rend, l’allemand change de préposition.","documents":[{"id":"tom","type":"dialogue","modele":"sms","titre":"Termine","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Wo bist du gerade?"},{"qui":"Tom","texte":"Ich bin beim Arzt. Danach gehe ich auf die Post."},{"qui":"Lea","texte":"Und am Wochenende?"},{"qui":"Tom","texte":"Ich fahre ans Meer, und danach aufs Land zu meiner Tante."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit que Tom est chez le médecin (sans mouvement).","aide":"Il répond à *wo ?* et se termine par -m.","type":"zone","document":"tom","multiple":false},{"enonce":"Touche le mot qui dit que Tom va au bord de la mer.","aide":"Il répond à *wohin ?* et se termine par -s.","type":"zone","document":"tom","multiple":false},{"enonce":"Range chaque expression : avec ou sans mouvement ?","aide":"Les formes contractées en *-s* (*ans*, *aufs*) sont des accusatifs : elles disent un mouvement.","type":"categories","categories":[{"id":"c0","texte":"Avec mouvement (wohin ?)"},{"id":"c1","texte":"Sans mouvement (wo ?)"}],"items":[{"id":"i0","texte":"nach Hause"},{"id":"i1","texte":"auf dem Land"},{"id":"i2","texte":"ans Meer"},{"id":"i3","texte":"am Meer"},{"id":"i4","texte":"aufs Land"},{"id":"i5","texte":"zu Hause"}]},{"enonce":"Complète : « Je vais chez ma grand-mère et je suis ensuite chez elle. »","aide":"Aller chez quelqu’un : *zu*. Être chez quelqu’un : *bei*.","type":"trous","segments":["Ich gehe ",0," meiner Oma und bin dann ",1," meiner Oma."],"banque":["nach","aus","zu","bei"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**beim** = *bei dem* : on est chez le médecin, sans mouvement. Pour y aller, on dirait *zum Arzt*."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**ans** = *an das* : *an* + accusatif, car il y a un mouvement vers le bord de la mer."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"*ans Meer*, *aufs Land* et *nach Hause* disent un **mouvement** ; *am Meer*, *auf dem Land* et *zu Hause* disent un **lieu**. Elles vont toujours par paires."},{"cle":{"type":"trous","trous":[["zu"],["bei"]]},"affichage":"zu · bei","explication":"**zu meiner Oma** (mouvement vers une personne) et **bei meiner Oma** (lieu). Le français dit « chez » dans les deux cas, pas l’allemand."}]$ex$::jsonb),
  ('3fbce238-20b2-58e6-8151-86349b454de2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Plan de voyage en Europe","competence":"lire-carte","situation":"Un jeune voyageur prépare un parcours en Europe. Une carte montre les pays traversés ; son courriel dit comment il y va, d’où il revient et où il séjourne.","documents":[{"id":"karte","type":"carte","titre":"Reiseziele","fond":"europe","cadrage":[-6,40,22,56],"regions":[{"code":"FRA","teinte":"ciel","etiquette":"Frankreich"},{"code":"DEU","teinte":"ciel","etiquette":"Deutschland"},{"code":"CHE","teinte":"ciel","etiquette":"Schweiz"},{"code":"AUT","teinte":"ciel","etiquette":"Österreich"}],"regionsCliquables":true,"source":"Carte écrite pour l’exercice"},{"id":"mail","type":"texte","genre":"lettre","titre":"Hallo Clara","blocs":["Ich komme gerade von der Arbeit. Morgen fahre ich nach Wien, am Samstag dann in die Schweiz, zu meinem Bruder. Er lebt seit zwei Jahren im Ausland."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pays devant lequel on dit « in die » pour y aller.","aide":"Parmi ces pays, un seul a un article.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche le pays où se trouve Wien.","aide":"Wien est la capitale de ce pays voisin de l’Allemagne.","type":"zone","document":"karte","multiple":false},{"enonce":"Touche la préposition qui dit d’où revient le voyageur (l’origine).","aide":"Elle est devant *der Arbeit*.","type":"zone","document":"mail","multiple":false},{"enonce":"Complète : « Ma tante habite à la campagne. Aujourd’hui, nous allons à la campagne. »","aide":"Premier trou : lieu (datif). Deuxième trou : mouvement (accusatif contracté).","type":"trous","segments":["Meine Tante wohnt ",0," Land. Heute fahren wir ",1," Land."],"banque":["auf den","ans","auf dem","aufs"]},{"enonce":"Remets en ordre : « Je reviens de mon travail. » La phrase commence par Ich.","aide":"*von* est suivi du datif.","type":"ordre","items":[{"id":"a","texte":"von"},{"id":"b","texte":"komme"},{"id":"c","texte":"Ich"},{"id":"d","texte":"der Arbeit"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["CHE"]},"explication":"**La Suisse** : *in die Schweiz*. Les pays avec article (*die Schweiz*, *die Türkei*) demandent *in* + accusatif ; les autres demandent *nach* (*nach Österreich*, *nach Frankreich*)."},{"cle":{"type":"zone","ids":["AUT"]},"explication":"**L’Autriche** : *nach Wien*. Une ville sans article se dit avec *nach*."},{"cle":{"type":"zone","ids":["m3"]},"explication":"**von** : *von der Arbeit* indique un point de départ ; elle répond à la question *woher ?*."},{"cle":{"type":"trous","trous":[["auf dem"],["aufs","auf das"]]},"affichage":"auf dem · aufs","explication":"**auf dem Land** (où ? datif) et **aufs Land** (où ? accusatif, *auf das* contracté en *aufs*) : l’expression se présente par paires."},{"cle":{"type":"ordre","ids":["c","b","a","d"]},"explication":"**Ich komme von der Arbeit.** *von* + datif féminin (*der Arbeit*) indique l’origine."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 3e (8) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
